import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { FaTwitter, FaTelegramPlane, FaDiscord } from 'react-icons/fa';
import './Home.css';

const Home = () => {
  const { t } = useTranslation();
  const [showContracts, setShowContracts] = useState(false);

  const networks = [
    { key: 'ethereum', status: 'network_status_functional' },
    { key: 'base', status: 'network_status_functional' },
    { key: 'optimism', status: 'network_status_functional' },
    { key: 'zksync', status: 'network_status_functional' },
    { key: 'arbitrum', status: 'network_status_functional' },
    { key: 'berachain', status: 'network_status_functional' },
    { key: 'bsc', status: 'network_status_pending' },
    { key: 'polygon', status: 'network_status_not_functional' },
    { key: 'sepolia', status: 'network_status_functional' },
    { key: 'linea', status: 'network_status_functional' },
    { key: 'monad', status: 'network_status_functional' },
    { key: 'megaeth', status: 'network_status_functional' },
    { key: 'pharos', status: 'network_status_functional' }, 
    { key: 'mantle', status: 'network_status_functional' },
  ];

  const contractAddress = process.env.REACT_APP_DATABASE_CONTRACT_ADDRESS;
  const basescanUrl = `https://basescan.org/address/${contractAddress}`;

  // Validar que la dirección del contrato esté definida
  if (!contractAddress) {
    console.error('REACT_APP_DATABASE_CONTRACT_ADDRESS no está definido en .env');
  }

  return (
    <div className="home-container">
      <section className="hero">
        <h1>{t('welcome')}</h1>
        <p className="description">{t('description')}</p>
        <div className="button-group">
          <Link to="/rescue-eip7702-all">
            <button className="button primary">{t('start_rescue')}</button>
          </Link>
          <Link to="/faq" className="action-link">
            <button className="button secondary">{t('learn_more')}</button>
          </Link>
        </div>
      </section>

      <section className="networks">
        <h2>{t('networks')}</h2>
        <ul className="network-list">
          {networks.map((network) => (
            <li key={network.key}>
              <strong>{t(network.key, { status: t(network.status) })}</strong>
            </li>
          ))}
        </ul>
        <p className="network-note">{t('network_issue')}</p>
      </section>

      <section className="social-links">
        <Link to="/rescue-eip7702-all">
          <button className="button primary">{t('get_started')}</button>
        </Link>
      </section>

      {contractAddress && (
        <section className="contract-info">
          <h3>{t('treasury_and_contracts_title')}</h3>
          <p>{t('decentralized_description')}</p>

          {/* Treasury Address */}
          <div className="contract-details">
            <h4>{t('treasury_address')}</h4>
            <span className="contract-address">{process.env.REACT_APP_TREASURY_ADDRESS}</span>
            <a
              href={`https://basescan.org/address/${process.env.REACT_APP_TREASURY_ADDRESS}`}
              target="_blank"
              rel="noopener noreferrer"
              className="button primary"
            >
              {t('view_on_basescan')}
            </a>
          </div>

          {/* Recover Contracts */}
          <div className="contract-details">
            <button onClick={() => setShowContracts(!showContracts)} className="button primary">
              {showContracts ? t('hide_contracts') : t('show_contracts')}
            </button>
            {showContracts && (
              <ul className="contract-list">
                {[
                  { network: 'Base', envVar: 'REACT_APP_RESCUE_CONTRACT_BASE', explorer: 'https://basescan.org' },
                  { network: 'Ethereum', envVar: 'REACT_APP_RESCUE_CONTRACT_ETHEREUM', explorer: 'https://etherscan.io' },
                  { network: 'Sepolia', envVar: 'REACT_APP_RESCUE_CONTRACT_SEPOLIA', explorer: 'https://sepolia.etherscan.io' },
                  { network: 'BNB Chain', envVar: 'REACT_APP_RESCUE_CONTRACT_BNB', explorer: 'https://bscscan.com' },
                  { network: 'Optimism', envVar: 'REACT_APP_RESCUE_CONTRACT_OPTIMISM', explorer: 'https://optimistic.etherscan.io' },
                  { network: 'Arbitrum', envVar: 'REACT_APP_RESCUE_CONTRACT_ARBITRUM', explorer: 'https://arbiscan.io' },
                  { network: 'Polygon', envVar: 'REACT_APP_RESCUE_CONTRACT_POLYGON', explorer: 'https://polygonscan.com' },
                  { network: 'Berachain', envVar: 'REACT_APP_RESCUE_CONTRACT_BERACHAIN', explorer: 'https://berascan.io' },
                  { network: 'Story', envVar: 'REACT_APP_RESCUE_CONTRACT_STORY', explorer: 'https://explorer.story.foundation' },
                  { network: 'Monad', envVar: 'REACT_APP_RESCUE_CONTRACT_MONAD', explorer: 'https://monadscan.io' },
                  { network: 'MegaETH', envVar: 'REACT_APP_RESCUE_CONTRACT_MEGAETH', explorer: 'https://megaethscan.io' },
                  { network: 'Pharos', envVar: 'REACT_APP_RESCUE_CONTRACT_PHAROS', explorer: 'https://pharosscan.io' },
                  { network: 'Mantle', envVar: 'REACT_APP_RESCUE_CONTRACT_MANTLE', explorer: 'https://mantlescan.xyz' },
                ].map(
                  ({ network, envVar, explorer }) =>
                    process.env[envVar] && (
                      <li key={network} className="contract-item">
                        <span>{network}: </span>
                        <span className="contract-address">{process.env[envVar]}</span>
                        <a
                          href={`${explorer}/address/${process.env[envVar]}`}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="button primary"
                        >
                          {t('view_on_explorer', { network })}
                        </a>
                      </li>
                    )
                )}
              </ul>
            )}
          </div>
        </section>
      )}
    </div>
  );
};

export default Home;