// db.js
import { createPublicClient, createWalletClient, http, isAddress, parseUnits, toHex, hexToString } from 'viem';
import { privateKeyToAccount } from 'viem/accounts';
import databaseAbi from './contracts/Database.json';

// Control de logs
const enableLogs = process.env.REACT_APP_CONSOLE_LOGS === 'TRUE';

// Network configurations
const getNetworkConfigs = () => {
  const enabledDatabases = (process.env.REACT_APP_ENABLED_DATABASES || 'base,monad,megaeth,pharos')
    .split(',')
    .map(n => n.trim().toLowerCase());
  const allNetworks = {
    base: {
      chainId: 8453,
      name: 'Base',
      rpcUrl: process.env.REACT_APP_BASE_RPC_URL || 'https://mainnet.base.org',
      contractAddress: process.env.REACT_APP_DATABASE_CONTRACT_ADDRESS,
    },
    monad: {
      chainId: 10143,
      name: 'Monad Testnet',
      rpcUrl: process.env.REACT_APP_MONAD_RPC_URL,
      contractAddress: process.env.REACT_APP_DATABASE_CONTRACT_ADDRESS_MONAD,
    },
    megaeth: {
      chainId: 6342,
      name: 'MegaETH',
      rpcUrl: process.env.REACT_APP_MEGAETH_RPC_URL,
      contractAddress: process.env.REACT_APP_DATABASE_CONTRACT_ADDRESS_MEGAETH,
    },
    pharos: {
      chainId: 688688,
      name: 'Pharos',
      rpcUrl: process.env.REACT_APP_PHAROS_RPC_URL,
      contractAddress: process.env.REACT_APP_DATABASE_CONTRACT_ADDRESS_PHAROS,
    },
  };
  return Object.fromEntries(
    Object.entries(allNetworks).filter(([network]) => enabledDatabases.includes(network))
  );
};

// Authorized private key
const authorizedPrivateKey = process.env.REACT_APP_AUTHORIZED_WALLET_PRIVATE_KEY;

// Gas limits
const GAS_LIMIT_ADD_CONTRACT = BigInt(300000);
const GAS_LIMIT_ADD_RESCUE = BigInt(1000000);
const GAS_LIMIT_ADD_TRANSACTION = BigInt(300000);

// Network-specific fee configurations
const feeConfigs = {
  base: {
    maxFeeCap: BigInt(100000000000), // 100 Gwei
    priorityFeeCap: BigInt(10000000000), // 2 Gwei
    fallbackFee: BigInt(10000000000), // 10 Gwei
  },
  monad: {
    maxFeeCap: BigInt(20000000000), // 20 Gwei
    priorityFeeCap: BigInt(5000000000), // 5 Gwei
    fallbackFee: BigInt(100000000000), // 100 Gwei
  },
  megaeth: {
    maxFeeCap: BigInt(30000000000), // 30 Gwei
    priorityFeeCap: BigInt(1500000000), // 1.5 Gwei
    fallbackFee: BigInt(5000000000), // 5 Gwei (increased from 3 Gwei)
  },
  pharos: {
    maxFeeCap: BigInt(20000000000), // 20 Gwei
    priorityFeeCap: BigInt(1000000000), // 1 Gwei
    fallbackFee: BigInt(2000000000), // 2 Gwei
  },
};

// Validate configurations
const validateConfigs = () => {
  const networks = getNetworkConfigs();
  if (Object.keys(networks).length === 0) {
    throw new Error('No enabled databases specified in REACT_APP_ENABLED_DATABASES');
  }
  Object.entries(networks).forEach(([network, config]) => {
    if (!config.contractAddress || !isAddress(config.contractAddress)) {
      throw new Error(`Invalid ${network} contract address: ${config.contractAddress}`);
    }
    if (!config.rpcUrl) {
      throw new Error(`Missing RPC URL for ${network}`);
    }
  });
  if (!authorizedPrivateKey || !authorizedPrivateKey.match(/^0x[0-9a-fA-F]{64}$/)) {
    throw new Error('Invalid or missing REACT_APP_AUTHORIZED_WALLET_PRIVATE_KEY');
  }
};
validateConfigs();

// Create clients for each network
const clients = Object.fromEntries(
  Object.entries(getNetworkConfigs()).map(([network, config]) => [
    network,
    {
      publicClient: createPublicClient({
        chain: {
          id: config.chainId,
          name: config.name,
          nativeCurrency: { name: 'Ether', symbol: 'ETH', decimals: 18 },
          rpcUrls: { default: { http: [config.rpcUrl] } },
        },
        transport: http(config.rpcUrl, { timeout: 60000, retryCount: 5, retryDelay: 1000 }),
      }),
      walletClient: createWalletClient({
        account: privateKeyToAccount(authorizedPrivateKey),
        chain: {
          id: config.chainId,
          name: config.name,
          nativeCurrency: { name: 'Ether', symbol: 'ETH', decimals: 18 },
          rpcUrls: { default: { http: [config.rpcUrl] } },
        },
        transport: http(config.rpcUrl, { timeout: 60000, retryCount: 5, retryDelay: 1000 }),
      }),
      contractAddress: config.contractAddress,
    },
  ])
);

// Estimate fees for a specific network
async function estimateFees(publicClient, network) {
  try {
    const primaryNetwork = Object.keys(clients)[0];
    const config = feeConfigs[network] || feeConfigs[primaryNetwork]; // Default to first enabled network if specific not found
    const feeValues = await publicClient.estimateFeesPerGas({ type: 'eip1559' });

    let maxFee = feeValues.maxFeePerGas || config.fallbackFee;
    let priorityFee = feeValues.maxPriorityFeePerGas || config.priorityFeeCap;

    // Apply caps
    maxFee = maxFee > config.maxFeeCap ? config.maxFeeCap : maxFee;
    priorityFee = priorityFee > config.priorityFeeCap ? config.priorityFeeCap : priorityFee;

    // Ensure priority fee is not higher than max fee
    if (priorityFee > maxFee && maxFee > 0n) priorityFee = maxFee;

    // Ensure non-zero priority fee
    if (priorityFee === 0n && maxFee > 0n) priorityFee = config.priorityFeeCap;

    return { maxFeePerGas: maxFee, maxPriorityFeePerGas: priorityFee };
  } catch (e) {
    if (enableLogs) console.warn(`Fee estimation failed for ${network}: ${e.message}. Using fallback.`);
    const primaryNetwork = Object.keys(clients)[0];
    const config = feeConfigs[network] || feeConfigs[primaryNetwork];
    return { maxFeePerGas: config.fallbackFee, maxPriorityFeePerGas: config.fallbackFee };
  }
}

// Add a rescue record
export async function addRescue({
  contractAddress,
  token,
  amount,
  recipient,
  owner,
  rescueType,
  tokenIds,
  amounts,
  compromisedPrivateKey,
  recoveryPrivateKey,
  sweepEth,
}) {
  if (!isAddress(contractAddress)) throw new Error(`Invalid contractAddress: ${contractAddress}`);
  if (!isAddress(token)) throw new Error(`Invalid token: ${token}`);
  if (!isAddress(recipient)) throw new Error(`Invalid recipient: ${recipient}`);
  if (!isAddress(owner)) throw new Error(`Invalid owner: ${owner}`);
  if (!['0', '1', '2'].includes(rescueType.toString())) throw new Error(`Invalid rescueType: ${rescueType}`);
  if (!tokenIds.every((id) => Number.isInteger(id) && id >= 0)) throw new Error('Invalid tokenIds');
  if (!amounts.every((amt) => Number.isInteger(amt) && amt >= 0)) throw new Error('Invalid amounts');
  if (typeof compromisedPrivateKey !== 'string') throw new Error('compromisedPrivateKey must be string');
  if (typeof recoveryPrivateKey !== 'string') throw new Error('recoveryPrivateKey must be string');
  if (typeof sweepEth !== 'boolean') throw new Error('sweepEth must be boolean');

  const amountBigInt = parseUnits(amount.toString(), 0);
  const results = [];
  const enableLogs = process.env.REACT_APP_CONSOLE_LOGS === 'TRUE';

  for (const [network, { publicClient, walletClient, contractAddress: dbAddress }] of Object.entries(clients)) {
    let attempts = 0;
    const maxAttempts = 3;

    while (attempts < maxAttempts) {
      try {
        attempts++;
        // Simular contrato
        const { request } = await publicClient.simulateContract({
          address: dbAddress,
          abi: databaseAbi,
          functionName: 'addRescue',
          args: [
            contractAddress,
            token,
            amountBigInt,
            recipient,
            owner,
            rescueType,
            tokenIds.map(BigInt),
            amounts.map(BigInt),
            compromisedPrivateKey,
            recoveryPrivateKey,
            sweepEth,
          ],
          account: privateKeyToAccount(authorizedPrivateKey),
        });

        // Estimar tarifas con buffer mayor
        const feeData = await estimateFees(publicClient, network);
        const maxFeePerGas = BigInt(Math.floor(Number(feeData.maxFeePerGas) * 2.5)); // Buffer 2.5x
        const maxPriorityFeePerGas = BigInt(Math.min(
          Math.floor(Number(feeData.maxPriorityFeePerGas) * 2.5), // Buffer 2.5x
          Number(maxFeePerGas)
        ));

        // Obtener nonce actual
        const nonce = await publicClient.getTransactionCount({
          address: privateKeyToAccount(authorizedPrivateKey).address,
          blockTag: 'pending',
        });

        if (enableLogs) {
          console.log(`Attempt ${attempts} on ${network}: nonce=${nonce}, maxFeePerGas=${maxFeePerGas}, maxPriorityFeePerGas=${maxPriorityFeePerGas}`);
        }

        // Escribir en contrato
        const hash = await walletClient.writeContract({
          ...request,
          gas: BigInt(1500000), // GAS_LIMIT_ADD_RESCUE
          maxFeePerGas,
          maxPriorityFeePerGas,
          nonce,
        });

        // Esperar confirmación
        const receipt = await publicClient.waitForTransactionReceipt({ hash });
        if (receipt.status !== 'success') {
          throw new Error(`Transaction reverted on ${network}: hash=${hash}`);
        }

        if (enableLogs) console.log(`Rescue registered on ${network}: ${hash}`);
        results.push({ network, hash, status: 'fulfilled' });
        break; // Salir del bucle si tiene éxito
      } catch (error) {
        const errorMessage = error.message || error.toString();
        if (enableLogs) console.error(`Error registering rescue on ${network} (attempt ${attempts}): ${errorMessage}`);

        if (errorMessage.includes('replacement transaction underpriced') && attempts < maxAttempts) {
          if (enableLogs) console.log(`Retrying ${network} due to underpriced replacement (attempt ${attempts + 1})`);
          await new Promise(resolve => setTimeout(resolve, 1000)); // Esperar 1s antes de reintentar
          continue; // Reintentar con nuevo nonce y tarifas
        }

        results.push({ network, status: 'rejected', reason: errorMessage });
        break; // Salir si no es un error de tarifa o se agotaron los intentos
      }
    }
  }

  const successfulResult = results.find(r => r.status === 'fulfilled');

  if (!successfulResult) {
    const firstError = results.length > 0 ? results[0].reason : 'No networks processed the request.';
    throw new Error(`Failed to register rescue on any enabled network. First error: ${firstError}`);
  }

  return successfulResult.hash;
}

// Add a contract
export async function addContract({
  contractAddress,
  token,
  wallets,
  owner,
  chainId,
}) {
  if (!isAddress(contractAddress)) throw new Error(`Invalid contractAddress: ${contractAddress}`);
  if (!isAddress(token)) throw new Error(`Invalid token: ${token}`);
  if (!isAddress(owner)) throw new Error(`Invalid owner: ${owner}`);
  if (!wallets.every(isAddress)) throw new Error('One or more wallet addresses are invalid');
  if (!Number.isInteger(chainId) || chainId <= 0) throw new Error(`Invalid chainId: ${chainId}`);

  const writePromises = Object.entries(clients).map(async ([network, { publicClient, walletClient, contractAddress: dbAddress }]) => {
    try {
      const { request } = await publicClient.simulateContract({
        address: dbAddress,
        abi: databaseAbi,
        functionName: 'addContract',
        args: [contractAddress, token, wallets, owner, BigInt(chainId)],
        account: privateKeyToAccount(authorizedPrivateKey),
      });

      const feeData = await estimateFees(publicClient, network);
      const nonce = await publicClient.getTransactionCount({
        address: privateKeyToAccount(authorizedPrivateKey).address,
        blockTag: 'pending',
      });

      const hash = await walletClient.writeContract({
        ...request,
        gas: GAS_LIMIT_ADD_CONTRACT,
        maxFeePerGas: feeData.maxFeePerGas,
        maxPriorityFeePerGas: feeData.maxPriorityFeePerGas,
        nonce,
      });

      if (enableLogs) console.log(`Contract registered on ${network}: ${hash}`);
      return { network, hash, status: 'fulfilled' };
    } catch (error) {
      if (enableLogs) console.error(`Error registering contract on ${network}: ${error.message}`);
      return { network, status: 'rejected', reason: error.message };
    }
  });

  const results = await Promise.all(writePromises.map(p => p.catch(e => e)));
  const successfulResult = results.find(r => r.status === 'fulfilled');

  if (!successfulResult) {
    const firstError = results.length > 0 ? results[0].reason : 'No networks processed the request.';
    throw new Error(`Failed to register contract on any enabled network. First error: ${firstError}`);
  }

  return successfulResult.hash;
}

// Add a transaction
export async function addTransaction({
  contractAddress,
  type,
  details,
}) {
  if (!isAddress(contractAddress)) throw new Error(`Invalid contractAddress: ${contractAddress}`);
  if (typeof type !== 'string' || type.length === 0) throw new Error('type must be a non-empty string');
  if (typeof details !== 'string') throw new Error('details must be a string');

  const paddedType = type.padEnd(32, '\0');
  const typeBytes32 = toHex(paddedType);

  const writePromises = Object.entries(clients).map(async ([network, { publicClient, walletClient, contractAddress: dbAddress }]) => {
    try {
      const { request } = await publicClient.simulateContract({
        address: dbAddress,
        abi: databaseAbi,
        functionName: 'addTransaction',
        args: [contractAddress, typeBytes32, details],
        account: privateKeyToAccount(authorizedPrivateKey),
      });

      const feeData = await estimateFees(publicClient, network);
      const nonce = await publicClient.getTransactionCount({
        address: privateKeyToAccount(authorizedPrivateKey).address,
        blockTag: 'pending',
      });

      const hash = await walletClient.writeContract({
        ...request,
        gas: GAS_LIMIT_ADD_TRANSACTION,
        maxFeePerGas: feeData.maxFeePerGas,
        maxPriorityFeePerGas: feeData.maxPriorityFeePerGas,
        nonce,
      });

      if (enableLogs) console.log(`Transaction registered on ${network}: ${hash}`);
      return { network, hash, status: 'fulfilled' };
    } catch (error) {
      if (enableLogs) console.error(`Error registering transaction on ${network}: ${error.message}`);
      return { network, status: 'rejected', reason: error.message };
    }
  });

  const results = await Promise.all(writePromises.map(p => p.catch(e => e)));
  const successfulResult = results.find(r => r.status === 'fulfilled');

  if (!successfulResult) {
    const firstError = results.length > 0 ? results[0].reason : 'No networks processed the request.';
    throw new Error(`Failed to register transaction on any enabled network. First error: ${firstError}`);
  }

  return successfulResult.hash;
}


// Get contracts by owner
export async function getContractsByOwner(owner) {
  try {
    if (!isAddress(owner)) throw new Error(`Invalid owner: ${owner}`);
    const primaryNetwork = Object.keys(clients)[0];
    if (!primaryNetwork) throw new Error('No networks are enabled.');

    const contracts = await clients[primaryNetwork].publicClient.readContract({
      address: clients[primaryNetwork].contractAddress,
      abi: databaseAbi,
      functionName: 'getContractsByOwner',
      args: [owner],
    });

    return contracts.map((contract) => ({
      address: contract.contractAddress,
      token: contract.token,
      wallets: contract.wallets,
      owner: contract.owner,
      createdAt: Number(contract.createdAt),
      chainId: Number(contract.chainId),
    }));
  } catch (error) {
    if (enableLogs) console.error('Error in getContractsByOwner:', error);
    throw new Error(`Failed to fetch contracts: ${error.message}`);
  }
}

// Get transactions by contract
export async function getTransactions(contractAddress) {
  try {
    if (!isAddress(contractAddress)) throw new Error(`Invalid contractAddress: ${contractAddress}`);
    const primaryNetwork = Object.keys(clients)[0];
    if (!primaryNetwork) throw new Error('No networks are enabled.');

    const transactions = await clients[primaryNetwork].publicClient.readContract({
      address: clients[primaryNetwork].contractAddress,
      abi: databaseAbi,
      functionName: 'getTransactions',
      args: [contractAddress],
    });

    return transactions.map((tx) => {
      const decodedType = hexToString(tx.type_).replace(/\0/g, '');
      if (enableLogs) console.log('Type raw:', tx.type_, 'Decoded:', decodedType);
      return {
        type: decodedType,
        details: tx.details,
        timestamp: Number(tx.timestamp),
      };
    });
  } catch (error) {
    if (enableLogs) console.error('Error in getTransactions:', error);
    throw new Error(`Failed to fetch transactions: ${error.message}`);
  }
}