// Configuración de cadenas desde .env
const envNetworks = Object.keys(process.env)
  .filter((key) => key.startsWith('REACT_APP_RPC_'))
  .map((key) => {
    const networkName = key.replace('REACT_APP_RPC_', '').toLowerCase();
    const rpcUrl = process.env[key];
    const chainIdMap = {
      'ethereum': 1,
      'polygon': 137,
      'bsc': 56,
      'arbitrum': 42161,
      'optimism': 10,
      'sepolia': 11155111,
      'berachain': 80094,
      'base': 8453,
      'monad': 10143,
      'linea': 59144,
      'mantle': 5000,
      'megaeth': 6342,
      'pharos': 688688
    };
    const chainId = chainIdMap[networkName] || parseInt(process.env[`REACT_APP_CHAINID_${networkName}`], 10);
    if (!chainId) {
      console.warn(`No chainId defined for ${networkName}. Define REACT_APP_CHAINID_${networkName} in .env`);
      return null;
    }
    return defineChain({
      id: chainId,
      name: networkName.charAt(0).toUpperCase() + networkName.slice(1),
      network: networkName,
      nativeCurrency: { name: 'Ether', symbol: 'ETH', decimals: 18 },
      rpcUrls: { default: { http: [rpcUrl] }, public: { http: [rpcUrl] } },
    });
  })
  .filter(Boolean);

