// Componente principal
const App = () => {
  const { t, i18n } = useTranslation();
  const [walletAddress, setWalletAddress] = useState(localStorage.getItem('walletAddress') || null);
  const [provider, setProvider] = useState(null);
  const [contracts, setContracts] = useState([]);
  const [selectedContract, setSelectedContract] = useState(null);
  const [transactions, setTransactions] = useState([]);
  const [theme, setTheme] = useState('dark');
  const [menuOpen, setMenuOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [avatarMenuOpen, setAvatarMenuOpen] = useState(false);
  const [permitMenuOpen, setPermitMenuOpen] = useState(false);
  const [bundleMenuOpen, setBundleMenuOpen] = useState(false);
  const [currentChainId, setCurrentChainId] = useState(null);
  const [isModalOpen, setIsModalOpen] = useState(false); // Changed initial state to false
  const [eip7702MenuOpen, setEip7702MenuOpen] = useState(false);
  const [searchPanelOpen, setSearchPanelOpen] = useState(false);
  const [isConnecting, setIsConnecting] = useState(false); // New state to track connection
  const menuRef = useRef(null);
  const sidebarRef = useRef(null);
  const avatarMenuRef = useRef(null);
  const permitMenuRef = useRef(null);
  const bundleMenuRef = useRef(null);
  const permitButtonRef = useRef(null);
  const bundleButtonRef = useRef(null);
  const menuButtonRef = useRef(null);
  const avatarButtonRef = useRef(null);
  const eip7702MenuRef = useRef(null);
  const eip7702ButtonRef = useRef(null);

  // Hooks de Reown AppKit
  const { open, close } = useAppKit();
  const { address, isConnected } = useAppKitAccount();
  const { walletProvider } = useAppKitProvider('eip155');
  const { selectedNetwork } = useAppKitNetwork();

  const changeLanguage = (lng) => {
    i18n.changeLanguage(lng);
  };
  
  const toggleSearchPanel = () => {
    setSearchPanelOpen((prev) => !prev);
  };

  const handleConnectWallet = useCallback(async () => {
    if (isConnecting) return; // Prevent multiple connection attempts
    setIsConnecting(true);
    try {
      await open();
      console.log('Solicitando conexión de wallet...');
    } catch (error) {
      console.error('Error al conectar wallet:', error);
    } finally {
      setIsConnecting(false);
    }
  }, [open, isConnecting]);

  const closeModal = () => {
    setIsModalOpen(false);
  };

  const supportedChains = Object.fromEntries(
    envNetworks.map((chain) => [chain.id, { name: chain.name, rpcUrl: chain.rpcUrls.default.http[0] }])
  );

  // Actualizar estado tras conexión
  const updateConnectionState = useCallback(async (address, chainId) => {
    if (!address || !isConnected || isConnecting) return;

    try {
      if (!walletProvider) {
        console.error('No se encontró walletProvider');
        return;
      }

      console.log('Actualizando estado de conexión:', { address, chainId });

      const ethersProvider = new ethers.providers.Web3Provider(walletProvider, 'any');
      const network = await ethersProvider.getNetwork();
      const resolvedChainId = chainId || network.chainId || envNetworks[0].id;
      
      setProvider(ethersProvider);
      setWalletAddress(address);
      setCurrentChainId(resolvedChainId);
      localStorage.setItem('walletAddress', address);

      await loadContracts(address);
      setSidebarOpen(true);
      setIsModalOpen(false);

      console.log('Estado actualizado:', { walletAddress: address, currentChainId: resolvedChainId, sidebarOpen: true });
    } catch (error) {
      console.error('Error actualizando estado de conexión:', error);
    }
  }, [isConnected, walletProvider, isConnecting]);

  useEffect(() => {
    if (selectedNetwork && selectedNetwork.chainId && walletAddress) {
      const newChainId = parseInt(selectedNetwork.chainId);
      console.log('Red seleccionada por Reown:', newChainId);
      if (newChainId !== currentChainId) {
        setCurrentChainId(newChainId);
        if (walletProvider) {
          const ethersProvider = new ethers.providers.Web3Provider(walletProvider, 'any');
          setProvider(ethersProvider);
        }
        loadContracts(walletAddress);
      }
    }
  }, [selectedNetwork, walletProvider, walletAddress, currentChainId]);

  useEffect(() => {
    if (isConnected && address && walletProvider && !isConnecting) {
      const chainId = selectedNetwork?.chainId ? parseInt(selectedNetwork.chainId) : null;
      console.log('Detectada conexión:', { address, chainId });
      updateConnectionState(address, chainId);
    }
    if (!isConnected) {
      disconnectWallet();
    }
  }, [isConnected, address, walletProvider, selectedNetwork, updateConnectionState, isConnecting]);

  const disconnectWallet = async () => {
    try {
      await open({ view: 'Account' });
      setProvider(null);
      setWalletAddress(null);
      setContracts([]);
      setSelectedContract(null);
      setTransactions([]);
      setCurrentChainId(null);
      setSidebarOpen(false);
      setIsModalOpen(true);
      localStorage.removeItem('walletAddress');
      console.log('Wallet desconectada');
    } catch (error) {
      console.error('Error al desconectar wallet:', error);
    }
  };

  const switchNetwork = async (chainId) => {
    try {
      if (walletProvider) {
        await walletProvider.request({
          method: 'wallet_switchEthereumChain',
          params: [{ chainId: `0x${chainId.toString(16)}` }],
        });
        const ethersProvider = new ethers.providers.Web3Provider(walletProvider, 'any');
        setProvider(ethersProvider);
        setCurrentChainId(chainId);
        await loadContracts(walletAddress);
        console.log('Red cambiada a:', chainId);
      }
    } catch (error) {
      if (error.code === 4902 && supportedChains[chainId]) {
        await walletProvider.request({
          method: 'wallet_addEthereumChain',
          params: [
            {
              chainId: `0x${chainId.toString(16)}`,
              chainName: supportedChains[chainId].name,
              rpcUrls: [supportedChains[chainId].rpcUrl],
              nativeCurrency: { name: 'ETH', symbol: 'ETH', decimals: 18 },
            },
          ],
        });
        await walletProvider.request({
          method: 'wallet_switchEthereumChain',
          params: [{ chainId: `0x${chainId.toString(16)}` }],
        });
        const ethersProvider = new ethers.providers.Web3Provider(walletProvider, 'any');
        setProvider(ethersProvider);
        setCurrentChainId(chainId);
        await loadContracts(walletAddress);
        console.log('Red añadida y cambiada a:', chainId);
      } else {
        console.error('Error cambiando de red:', error);
      }
    }
  };

  const loadContracts = async (owner) => {
    try {
      console.log('Cargando contratos para:', owner);
      const userContracts = await getContractsByOwner(owner);
      const updatedContracts = userContracts.map((contract) => ({
        ...contract,
        chainId: contract.chainId || currentChainId,
        network: supportedChains[contract.chainId || currentChainId]?.name || 'Unknown',
      }));
      setContracts(updatedContracts);
      if (updatedContracts.length > 0) {
        setSelectedContract(updatedContracts[0].address);
      } else {
        setSelectedContract(null);
      }
      console.log('Contratos cargados:', updatedContracts);
    } catch (error) {
      console.error('Error loading contracts:', error);
      setContracts([]);
      setSelectedContract(null);
    }
  };

  const loadTransactions = async (contractAddress) => {
    try {
      const txs = await getTransactions(contractAddress);
      setTransactions(txs);
      console.log('Transacciones cargadas:', txs);
    } catch (error) {
      console.error('Error loading transactions:', error);
      setTransactions([]);
    }
  };

  useEffect(() => {
    if (selectedContract && contracts.some((c) => c.address === selectedContract)) {
      loadTransactions(selectedContract);
    } else {
      setTransactions([]);
      setSelectedContract(contracts[0]?.address || null);
    }
  }, [selectedContract, contracts]);

  const toggleTheme = () => setTheme(theme === 'dark' ? 'light' : 'dark');

  const toggleMenu = (e) => {
    e.stopPropagation();
    e.preventDefault();
    setMenuOpen((prev) => !prev);
    setPermitMenuOpen(false);
    setBundleMenuOpen(false);
    setEip7702MenuOpen(false);
  };

  const toggleSidebar = (e) => {
    if (e) e.stopPropagation();
    setSidebarOpen((prev) => !prev);
  };

  const toggleAvatarMenu = (e) => {
    if (e) e.stopPropagation();
    setAvatarMenuOpen((prev) => !prev);
  };

  const togglePermitMenu = (e) => {
    e.stopPropagation();
    e.preventDefault();
    setPermitMenuOpen((prev) => !prev);
    setMenuOpen(true);
    setBundleMenuOpen(false);
    setEip7702MenuOpen(false);
  };

  const toggleBundleMenu = (e) => {
    e.stopPropagation();
    e.preventDefault();
    setBundleMenuOpen((prev) => !prev);
    setMenuOpen(true); 
    setPermitMenuOpen(false);
    setEip7702MenuOpen(false);
  };

  const toggleEip7702Menu = (e) => {
    e.stopPropagation();
    e.preventDefault();
    setEip7702MenuOpen((prev) => !prev);
    setMenuOpen(true);
    setPermitMenuOpen(false);
    setBundleMenuOpen(false);
  };

  const handleAvatarClick = (e) => {
    e.stopPropagation();
    e.preventDefault();
    if (window.innerWidth <= 768) {
      setSidebarOpen((prev) => !prev);
    } else {
      setAvatarMenuOpen((prev) => !prev);
    }
  };

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (
        menuRef.current &&
        !menuRef.current.contains(event.target) &&
        menuButtonRef.current &&
        !menuButtonRef.current.contains(event.target) &&
        menuOpen
      ) {
        setMenuOpen(false);
      }
      if (sidebarRef.current && !sidebarRef.current.contains(event.target) && sidebarOpen) {
        setSidebarOpen(false);
      }
      if (
        avatarMenuRef.current &&
        !avatarMenuRef.current.contains(event.target) &&
        avatarButtonRef.current &&
        !avatarButtonRef.current.contains(event.target) &&
        avatarMenuOpen
      ) {
        setAvatarMenuOpen(false);
      }
      if (
        permitMenuRef.current &&
        !permitMenuRef.current.contains(event.target) &&
        permitButtonRef.current &&
        !permitButtonRef.current.contains(event.target) &&
        permitMenuOpen
      ) {
        setPermitMenuOpen(false);
      }
      if (
        bundleMenuRef.current &&
        !bundleMenuRef.current.contains(event.target) &&
        bundleButtonRef.current &&
        !bundleButtonRef.current.contains(event.target) &&
        bundleMenuOpen
      ) {
        setBundleMenuOpen(false);
      }
      if (
        eip7702MenuRef.current &&
        !eip7702MenuRef.current.contains(event.target) &&
        eip7702ButtonRef.current &&
        !eip7702ButtonRef.current.contains(event.target) &&
        eip7702MenuOpen
      ) {
        setEip7702MenuOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [menuOpen, sidebarOpen, avatarMenuOpen, permitMenuOpen, bundleMenuOpen, eip7702MenuOpen]);

  const AvatarInfo = () => {
    const { t } = useTranslation();
    const { disconnect } = useDisconnect();
    const chainName = supportedChains[currentChainId]?.name || 'Unknown';

    const handleDisconnect = async () => {
      try {
        await disconnect();
      } catch (error) {
        console.error('Error disconnecting wallet:', error);
      }
    };

    return (
      <div className="avatar-info">
        <p>WALLET: {walletAddress?.slice(0, 6)}...{walletAddress?.slice(-4)}</p>
        {walletAddress && (
          <appkit-network-button namespace="eip155"></appkit-network-button>
        )}
        <div className="social-icons">
          <a
            href="https://x.com/Edwin0x0"
            target="_blank"
            rel="noopener noreferrer"
            className="social-icon x-icon"
            title="Follow on X"
          >
            <FaTwitter />
          </a>
          <a
            href="https://t.me/dropsinsiderschat"
            target="_blank"
            rel="noopener noreferrer"
            className="social-icon telegram-icon"
            title="Join Telegram Group"
          >
            <FaTelegramPlane />
          </a>
          <a
            href="https://discord.gg/ZwqkqxY9ZR"
            target="_blank"
            rel="noopener noreferrer"
            className="social-icon discord-icon"
            title="Join Discord Server"
          >
            <FaDiscord />
          </a>
        </div>
        <button className="disconnect-button" onClick={handleDisconnect}>
          {t('disconnect_wallet')}
        </button>
      </div>
    );
  };

  return (
    <Router>
      <div className={`app-container ${theme}`}>
        <nav className="navbar">
          <div className="container">
            <div className="nav-logo">
              <Link to="/">
                <img src={logo} alt="DrainerLESS Logo" className="header-logo" />
              </Link>
              <Link to="/" className="nav-link">
                DrainerLESS
              </Link>
            </div>
            <div className={`nav-middle ${menuOpen ? 'active' : ''}`} ref={menuRef}>
              <div className="nav-item" ref={permitMenuRef}>
                <button className="nav-link" ref={permitButtonRef} onClick={togglePermitMenu}>
                  {t('permit_rescue')}
                </button>
                {permitMenuOpen && (
                  <div className="submenu">
                    <Link
                      to="/deploy"
                      className="nav-link"
                      onClick={() => {
                        setPermitMenuOpen(false);
                        setMenuOpen(false);
                      }}
                    >
                      {t('deploy')}
                    </Link>
                    <Link
                      to="/approve"
                      className="nav-link"
                      onClick={() => {
                        setPermitMenuOpen(false);
                        setMenuOpen(false);
                      }}
                    >
                      {t('approve')}
                    </Link>
                    <Link
                      to="/interact"
                      className="nav-link"
                      onClick={() => {
                        setPermitMenuOpen(false);
                        setMenuOpen(false);
                      }}
                    >
                      {t('interact')}
                    </Link>
                  </div>
                )}
              </div>
              <div className="nav-item" ref={bundleMenuRef}>
                <button className="nav-link" ref={bundleButtonRef} onClick={toggleBundleMenu}>
                  {t('bundle')}
                </button>
                {bundleMenuOpen && (
                  <div className="submenu">
                    <Link
                      to="/rescue"
                      className="nav-link"
                      onClick={() => {
                        switchNetwork(11155111);
                        setBundleMenuOpen(false);
                        setMenuOpen(false);
                      }}
                    >
                      Sepolia
                    </Link>
                    <Link
                      to="/rescue"
                      className="nav-link"
                      onClick={() => {
                        switchNetwork(1);
                        setBundleMenuOpen(false);
                        setMenuOpen(false);
                      }}
                    >
                      Ethereum Mainnet
                    </Link>
                  </div>
                )}
              </div>
              <div className="nav-item" ref={eip7702MenuRef}>
                <button className="nav-link" ref={eip7702ButtonRef} onClick={toggleEip7702Menu}>
                  EIP-7702 RESCUE
                </button>
                {eip7702MenuOpen && (
                  <div className="submenu">
                    <Link
                      to="/rescue-eip7702-tokens"
                      className="nav-link"
                      onClick={() => {
                        setEip7702MenuOpen(false);
                        setMenuOpen(false);
                      }}
                    >
                      Tokens (ERC20)
                    </Link>
                    <Link
                      to="/rescue-eip7702-nfts"
                      className="nav-link"
                      onClick={() => {
                        setEip7702MenuOpen(false);
                        setMenuOpen(false);
                      }}
                    >
                      NFTs
                    </Link>
                    <Link
                      to="/rescue-eip7702-all"
                      className="nav-link"
                      onClick={() => {
                        setEip7702MenuOpen(false);
                        setMenuOpen(false);
                      }}
                    >
                      COMPLETE RESCUE
                    </Link>
                    <Link
                      to="/rescue-eip7702-airdrop"
                      className="nav-link"
                      onClick={() => {
                        setEip7702MenuOpen(false);
                        setMenuOpen(false);
                      }}
                    >
                      AIRDROPS
                    </Link>
                  </div>
                )}
              </div>
              <Link to="/faq" className="nav-link" onClick={() => setMenuOpen(false)}>
                FAQ
              </Link>
            </div>
            <div className="nav-right">
              <button className="search-toggle" onClick={toggleSearchPanel}>
                🔍
              </button>
              {walletAddress ? (
                <>
                  <appkit-button balance="show" namespace="eip155"></appkit-button>
                  <button className="theme-toggle" onClick={toggleTheme}>
                    {theme === 'dark' ? '☀️' : '🌙'}
                  </button>
                  <div className="profile-container" ref={avatarMenuRef}>
                    <div className="avatar" ref={avatarButtonRef} onClick={handleAvatarClick}>
                      <img
                        src={`/avatars/avatar-${(walletAddress.slice(-1).charCodeAt(0) % 5) + 1}.png`}
                        alt="Avatar"
                      />
                    </div>
                    {avatarMenuOpen && (
                      <div className="avatar-menu">
                        <AvatarInfo />
                      </div>
                    )}
                  </div>
                </>
              ) : (
                <button className="connect-button" onClick={handleConnectWallet}>
                  {t('connect_wallet')}
                </button>
              )}
              <button className="navbar-menu-toggle" ref={menuButtonRef} onClick={toggleMenu}>
                {menuOpen ? '✖' : '☰'}
              </button>
            </div>
          </div>
        </nav>
        <div className="app-body">
          {walletAddress ? (
            <aside className={`profile-section ${sidebarOpen ? 'active' : ''}`} ref={sidebarRef}>
              <h2>{t('user_panel')}</h2>
              <p>WALLET: {walletAddress.slice(0, 6)}...{walletAddress.slice(-4)}</p>
              <h3>{t('contracts')}</h3>
              {contracts.length > 0 ? (
                contracts.map((contract) => (
                  <div key={contract.address} className="contract-item">
                    <button
                      onClick={() => {
                        setSelectedContract(contract.address);
                        setSidebarOpen(false);
                      }}
                      className={selectedContract === contract.address ? 'selected' : ''}
                    >
                      <span className="contract-address">
                        {contract.address.slice(0, 5)}...{contract.address.slice(-3)}
                      </span>
                      <span className="network-label">{contract.network}</span>
                    </button>
                    {selectedContract === contract.address && (
                      <div className="contract-actions">
                        <Link to="/approve" className="action-link" onClick={() => setSidebarOpen(false)}>
                          {t('approve')}
                        </Link>
                        <Link to="/interact" className="action-link" onClick={() => setSidebarOpen(false)}>
                          {t('interact')}
                        </Link>
                      </div>
                    )}
                  </div>
                ))
              ) : (
                <p>{t('no_contracts')}</p>
              )}
              {selectedContract && contracts.some((c) => c.address === selectedContract) && (
                <>
                  <h3>{t('transactions')}</h3>
                  {transactions.length > 0 ? (
                    transactions.map((tx, index) => (
                      <p key={index}>
                        {tx.type} - {tx.details} ({new Date(tx.timestamp * 1000).toLocaleString()})
                      </p>
                    ))
                  ) : (
                    <p>{t('no_transactions')}</p>
                  )}
                </>
              )}
              <div className="sidebar-footer">
                <AvatarInfo />
              </div>
            </aside>
          ) : (
            <Modal isOpen={isModalOpen} onClose={closeModal} onConnect={handleConnectWallet} />
          )}
          <main className="main-content">
            <Routes>
              <Route path="/" element={<Home />} />
              <Route
                path="/deploy"
                element={
                  walletAddress ? (
                    <DeployContract
                      onDeployed={async (addr, token, wallets) => {
                        const newContract = {
                          address: addr,
                          token,
                          wallets,
                          owner: walletAddress,
                          chainId: currentChainId,
                          network: supportedChains[currentChainId]?.name || 'Unknown',
                        };
                        try {
                          setContracts((prev) => [...prev, newContract]);
                          setSelectedContract(addr);
                          await loadContracts(walletAddress);
                        } catch (err) {
                          console.error('Error updating contracts:', err);
                          setContracts((prev) => [...prev, newContract]);
                          setSelectedContract(addr);
                        }
                      }}
                    />
                  ) : (
                    <Navigate to="/" />
                  )
                }
              />
              <Route
                path="/approve"
                element={
                  walletAddress && selectedContract && contracts.some((c) => c.address === selectedContract) ? (
                    <ApproveSpenderLoader
                      contractAddress={selectedContract}
                      tokenAddress={contracts.find((c) => c.address === selectedContract)?.token}
                    />
                  ) : (
                    <Navigate to="/" />
                  )
                }
              />
              <Route
                path="/interact"
                element={
                  walletAddress && selectedContract && contracts.some((c) => c.address === selectedContract) ? (
                    <InteractContract
                      contractAddress={selectedContract}
                      compromisedWallets={contracts.find((c) => c.address === selectedContract)?.wallets}
                    />
                  ) : (
                    <Navigate to="/" />
                  )
                }
              />
              <Route
                path="/rescue"
                element={
                  walletAddress && provider ? (
                    <RescueAssets walletAddress={walletAddress} provider={provider} />
                  ) : (
                    <Navigate to="/" />
                  )
                }
              />
              <Route
                path="/rescue-eip7702-tokens"
                element={
                  walletAddress && provider ? (
                    <RescueEIP7702 operationType="erc20" chainId={currentChainId} provider={provider} />
                  ) : (
                    <Navigate to="/" />
                  )
                }
              />
              <Route
                path="/rescue-eip7702-nfts"
                element={
                  walletAddress && provider ? (
                    <RescueEIP7702 operationType="nft" chainId={currentChainId} provider={provider} />
                  ) : (
                    <Navigate to="/" />
                  )
                }
              />
              <Route
                path="/rescue-eip7702-all"
                element={
                  walletAddress && provider ? (
                    <RescueEIP7702 operationType="all" chainId={currentChainId} provider={provider} />
                  ) : (
                    <Navigate to="/" />
                  )
                }
              />
              <Route
                path="/rescue-eip7702-airdrop"
                element={
                  walletAddress && provider ? (
                    <RescueEIP7702 operationType="airdrop" chainId={currentChainId} provider={provider} />
                  ) : (
                    <Navigate to="/" />
                  )
                }
              />
              <Route path="/faq" element={<FAQ />} />
            </Routes>
          </main>
         {searchPanelOpen && (
            <aside className="search-panel">
              <ChainSearch onClose={() => setSearchPanelOpen(false)} />
            </aside>
          )}
        </div>
        <div className="language-switcher">
          <button onClick={() => changeLanguage('en')}>EN</button>
          <button onClick={() => changeLanguage('es')}>ES</button>
        </div>
        <Footer />
      </div>
    </Router>
  );
};

export default App;