import React, { useState } from 'react';
import { ethers } from 'ethers';
import { useNavigate } from 'react-router-dom';
import './styles.css';

const ApproveSpenderBSC = ({ contractAddress, tokenAddress }) => {
  const [compromisedPrivateKeys, setCompromisedPrivateKeys] = useState('');
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const navigate = useNavigate();

  const approve = async () => {
    try {
      setLoading(true);
      setMessage('');

      const provider = new ethers.providers.Web3Provider(window.ethereum);
      const signer = provider.getSigner();
      const token = new ethers.Contract(tokenAddress, [
        "function permit(address owner, address spender, uint256 value, uint256 deadline, uint8 v, bytes32 r, bytes32 s) external",
        "function nonces(address owner) external view returns (uint256)",
        "function name() external view returns (string)",
        "function DOMAIN_SEPARATOR() external view returns (bytes32)"
      ], provider);

      const chainId = (await provider.getNetwork()).chainId;
      if (chainId !== 56) throw new Error('Este módulo es solo para BSC');

      // Ajustes específicos para BSC
      const tokenName = await token.name();
      const domain = {
        name: tokenName,
        version: '1', // Ajusta si el token usa otra versión (verifica en BscScan)
        chainId: 56, // Forzado para BSC
        verifyingContract: tokenAddress
      };
      const contractDomainSeparator = await token.DOMAIN_SEPARATOR();
      const computedDomainSeparator = ethers.utils._TypedDataEncoder.hashDomain(domain);
      console.log("Contract DOMAIN_SEPARATOR:", contractDomainSeparator);
      console.log("Computed DOMAIN_SEPARATOR:", computedDomainSeparator);

      const types = {
        Permit: [
          { name: 'owner', type: 'address' },
          { name: 'spender', type: 'address' },
          { name: 'value', type: 'uint256' },
          { name: 'nonce', type: 'uint256' },
          { name: 'deadline', type: 'uint256' }
        ]
      };

      const keysArray = compromisedPrivateKeys.split(',').map(key => key.trim());
      for (const privateKey of keysArray) {
        const compromisedWallet = new ethers.Wallet(privateKey, provider); // Conectar al proveedor
        const owner = compromisedWallet.address;

        const nonce = await token.nonces(owner);
        console.log("Nonce:", nonce.toString());
        const deadline = Math.floor(Date.now() / 1000) + 60 * 60; // 1 hora
        const value = ethers.constants.MaxUint256;

        const message = { owner, spender: contractAddress, value, nonce, deadline };
        console.log("Message:", message);

        const signature = await compromisedWallet._signTypedData(domain, types, message);
        const sig = ethers.utils.splitSignature(signature);
        console.log("Signature:", sig);

        // Intentar con permit
        const tx = await token.connect(signer).permit(
          owner,
          contractAddress,
          value,
          deadline,
          sig.v,
          sig.r,
          sig.s,
          { gasLimit: 300000, maxFeePerGas: ethers.utils.parseUnits('5', 'gwei'), maxPriorityFeePerGas: ethers.utils.parseUnits('3', 'gwei') }
        );
        await tx.wait();
        setMessage(`Aprobación completada para ${owner}`);
      }

      setLoading(false);
      navigate('/interact');
    } catch (error) {
      console.error("Error completo:", error);
      setMessage('Error: ' + error.message);
      setLoading(false);
    }
  };

  return (
    <div className="container">
      <h2>Aprobar Contrato (BSC)</h2>
      <p>Autoriza al contrato para manejar los tokens desde las wallets comprometidas en BSC:</p>
      <p className="warning">⚠ Solo usa claves privadas en un entorno seguro y privado.</p>
      <div className="form-group">
        <label>Claves Privadas Comprometidas</label>
        <textarea
          placeholder="0x123..., 0x456..."
          value={compromisedPrivateKeys}
          onChange={(e) => setCompromisedPrivateKeys(e.target.value)}
          rows="5"
          disabled={loading}
        />
        <small>Ingresa las claves privadas de las wallets comprometidas, separadas por comas.</small>
      </div>
      <div className="button-group">
        <button onClick={approve} disabled={loading}>
          {loading ? 'Aprobando...' : 'Aprobar Contrato'}
        </button>
      </div>
      {message && <p className={message.includes('Error') ? 'error' : 'success'}>{message}</p>}
    </div>
  );
};

export default ApproveSpenderBSC;