import { useAppKit } from '@reown/appkit/react';
import { useTranslation } from 'react-i18next';

const Modal = ({ isOpen, onClose }) => {
  const { t } = useTranslation();
  const { open } = useAppKit();

  if (!isOpen) return null;

  const handleConnect = async () => {
    try {
      onClose(); // Close the initial modal
      await open(); // Open the AppKit modal
    } catch (error) {
      console.error('Error opening AppKit modal:', error);
    }
  };

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-content" onClick={(e) => e.stopPropagation()}>
        <h2>{t('connect_wallet')}</h2>
        <p>{t('connect_wallet_prompt')}</p>
        <div className="modal-buttons">
          <button className="modal-button" onClick={handleConnect}>
            {t('connect')}
          </button>
          <button className="modal-button" onClick={onClose}>
            {t('no_connect')}
          </button>
        </div>
      </div>
    </div>
  );
};

export default Modal;