import React, { useState, useCallback } from 'react';
import { ethers } from 'ethers';
import { useNavigate } from 'react-router-dom';
import RescueTokensV3 from './contracts/RescueTokensV3.json';
import { addContract } from './db';
import './styles.css';

const DeployContract = ({ onDeployed }) => {
  const [safeWallet, setSafeWallet] = useState('');
  const [tokenContract, setTokenContract] = useState('');
  const [compromisedWalletsInput, setCompromisedWalletsInput] = useState('');
  const [deployedAddress, setDeployedAddress] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const navigate = useNavigate();
  const [isDeploying, setIsDeploying] = useState(false);

  const deploy = useCallback(async () => {
    if (isDeploying) {
      console.log('Despliegue en curso, ignorando llamada adicional');
      return;
    }
    console.log('Botón clicado, iniciando despliegue...');
    setIsDeploying(true);
    try {
      if (!window.ethereum) throw new Error('Por favor, instala MetaMask');
      setLoading(true);
      setError('');

      const provider = new ethers.providers.Web3Provider(window.ethereum);
      await provider.send('eth_requestAccounts', []);
      const signer = provider.getSigner();
      const owner = await signer.getAddress();
      const network = await provider.getNetwork();
      const chainId = network.chainId;

      if (!ethers.utils.isAddress(safeWallet) || !ethers.utils.isAddress(tokenContract))
        throw new Error('Direcciones inválidas');

      const compromisedWalletsArray = compromisedWalletsInput
        .split(',')
        .map(addr => addr.trim())
        .filter(addr => ethers.utils.isAddress(addr));
      if (compromisedWalletsArray.length === 0)
        throw new Error('Ingresa al menos una wallet comprometida válida');

      console.log('Desplegando contrato RescueTokensV3...');
      const factory = new ethers.ContractFactory(RescueTokensV3.abi, RescueTokensV3.bytecode, signer);
      const contract = await factory.deploy(safeWallet, tokenContract, compromisedWalletsArray);
      await contract.deployed();

      setDeployedAddress(contract.address);
      console.log(`Contrato desplegado en: ${contract.address}`);

      const contractData = {
      contractAddress: contract.address,
      token: tokenContract,
      wallets: compromisedWalletsArray,
      owner: owner,
      chainId: chainId,
    };
      console.log('Parámetros enviados a addContract:', contractData);
      await addContract(contractData);
      console.log(`Contrato registrado: ${contract.address}`);

      onDeployed(contract.address, tokenContract, compromisedWalletsArray, chainId);
      setSafeWallet('');
      setTokenContract('');
      setCompromisedWalletsInput('');
      navigate('/approve');
    } catch (error) {
      console.error('Error desplegando o registrando contrato:', error);
      setError(`Error: ${error.message}${error.reason ? ` (Razón: ${error.reason})` : ''}`);
    } finally {
      setLoading(false);
      setIsDeploying(false);
    }
  }, [safeWallet, tokenContract, compromisedWalletsInput, navigate, onDeployed, isDeploying]);

  return (
    <div className="container">
      <h2>Crear Contrato de Rescate</h2>
      <p>Configura tu contrato para rescatar tokens de wallets comprometidas:</p>
      <div className="form-group">
        <label>Wallet Segura</label>
        <input
          type="text"
          placeholder="0x..."
          value={safeWallet}
          onChange={(e) => setSafeWallet(e.target.value)}
          disabled={loading}
        />
        <small>La dirección donde se enviarán los tokens rescatados.</small>
      </div>
      <div className="form-group">
        <label>Contrato del Token</label>
        <input
          type="text"
          placeholder="0x..."
          value={tokenContract}
          onChange={(e) => setTokenContract(e.target.value)}
          disabled={loading}
        />
        <small>Dirección del token ERC-20 que deseas rescatar.</small>
      </div>
      <div className="form-group">
        <label>Wallets Comprometidas</label>
        <textarea
          placeholder="0x..., 0x..."
          value={compromisedWalletsInput}
          onChange={(e) => setCompromisedWalletsInput(e.target.value)}
          rows="3"
          disabled={loading}
        />
        <small>Lista de wallets comprometidas, separadas por comas.</small>
      </div>
      <div className="button-group">
        <button onClick={deploy} disabled={loading || isDeploying}>
          {loading ? 'Creando...' : 'Crear Contrato'}
        </button>
      </div>
      {deployedAddress && <p className="success">Contrato creado en: {deployedAddress}</p>}
      {error && <p className="error">{error}</p>}
    </div>
  );
};

export default DeployContract;