import React, { useState, useEffect } from 'react';
import { ethers } from 'ethers';
import { addRescue } from './db';
import './styles.css';

let FlashbotsBundleProvider;
try {
  FlashbotsBundleProvider = require('@flashbots/ethers-provider-bundle').FlashbotsBundleProvider;
} catch (error) {
  console.error('Failed to load FlashbotsBundleProvider:', error);
}

const erc20ABI = [
  'function transfer(address to, uint256 amount) external returns (bool)',
  'function balanceOf(address account) external view returns (uint256)',
  'function symbol() external view returns (string)',
  'function decimals() external view returns (uint8)',
];

const erc721ABI = [
  'function transferFrom(address from, address to, uint256 tokenId) external',
  'function balanceOf(address owner) external view returns (uint256)',
];

const RescueAssets = ({ walletAddress, provider }) => {
  const [assetType, setAssetType] = useState('');
  const [contractAddress, setContractAddress] = useState('');
  const [tokenIds, setTokenIds] = useState('');
  const [safeWalletAddress, setSafeWalletAddress] = useState('');
  const [hackedPrivateKey, setHackedPrivateKey] = useState('');
  const [sponsorPrivateKey, setSponsorPrivateKey] = useState('');
  const [chainId, setChainId] = useState('1');
  const [rpcUrl, setRpcUrl] = useState('https://eth.drpc.org');
  const [flashbotsRelay, setFlashbotsRelay] = useState('https://rpc.flashbots.net');
  const [logs, setLogs] = useState([]);
  const [isRescuing, setIsRescuing] = useState(false);

  const addLog = (message) => setLogs((prev) => [...prev, message]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!ethers.utils.isAddress(contractAddress) || !ethers.utils.isAddress(safeWalletAddress)) {
      addLog('Invalid contract or safe wallet address');
      return;
    }
    if (!hackedPrivateKey || hackedPrivateKey.length < 64 || !sponsorPrivateKey || sponsorPrivateKey.length < 64) {
      addLog('Invalid or missing private keys');
      return;
    }
    setIsRescuing(true);
    setLogs([]);
    await executeSafeTransfer();
    setIsRescuing(false);
  };

  const prepareTransferTxs = async (contract, hackedWallet) => {
    try {
      if (!ethers.utils.isAddress(hackedWallet.address)) {
        addLog('COMPROMISED WALLET ADDRESS IS INVALID');
        return { txs: [], info: null };
      }
      if (assetType === 'ERC20') {
        addLog('VERIFYING ERC20 BALANCE...');
        const balance = await contract.balanceOf(hackedWallet.address);
        if (balance.isZero()) {
          addLog('ZERO TOKEN BALANCE');
          return { txs: [], info: null };
        }
        const symbol = await contract.symbol();
        const decimals = await contract.decimals();
        const formattedBalance = ethers.utils.formatUnits(balance, decimals);
        addLog(`DISCOVERED BALANCE: ${formattedBalance} ${symbol}`);
        const data = contract.interface.encodeFunctionData('transfer', [safeWalletAddress, balance]);
        const tx = { to: contractAddress, data };
        const info = { type: 'ERC20', amount: balance, symbol, decimals };
        return { txs: [tx], info };
      } else if (assetType === 'ERC721') {
        const tokenIdArray = tokenIds.split(',').map((id) => id.trim());
        if (!tokenIdArray.length) {
          addLog('NO TOKEN IDS PROVIDED');
          return { txs: [], info: null };
        }
        addLog(`PREPARING TO TRANSFER ${tokenIdArray.length} NFTs:`);
        tokenIdArray.forEach((id) => addLog(` ▸ Token ID #${id}`));
        const txs = tokenIdArray.map((tokenId) => {
          const data = contract.interface.encodeFunctionData('transferFrom', [
            hackedWallet.address,
            safeWalletAddress,
            tokenId,
          ]);
          return { to: contractAddress, data };
        });
        const info = { type: 'ERC721', tokenIds: tokenIdArray };
        return { txs, info };
      }
      return { txs: [], info: null };
    } catch (error) {
      addLog(`ERROR PREPARING TRANSACTIONS: ${error.message}`);
      return { txs: [], info: null };
    }
  };

  const executeSafeTransfer = async () => {
    try {
      if (!provider) {
        addLog('PRIVIDER UNAVAILABLE. USING RPC URL INSTEAD.');
      }
      if (!FlashbotsBundleProvider) {
        addLog('FLASHBOTS UNAVAILABLE IN THIS ENVIRONMENT.');
        return;
      }
      addLog('INITIALIZING FLASHBOTS RESCUE MODULE...');
      const rpcProvider = new ethers.providers.JsonRpcProvider(rpcUrl);
      let sponsorWallet, hackedWallet;
      try {
        sponsorWallet = new ethers.Wallet(sponsorPrivateKey, rpcProvider);
        hackedWallet = new ethers.Wallet(hackedPrivateKey, rpcProvider);
        addLog(`SPONSOR ADDRESS: ${sponsorWallet.address}`);
        addLog(`COMPROMISED ADDRESS: ${hackedWallet.address}`);
      } catch (error) {
        addLog(`INVALID PRIVATE KEY: ${error.message}`);
        return;
      }

      const flashbotsProvider = await FlashbotsBundleProvider.create(rpcProvider, sponsorWallet, flashbotsRelay);

      const contract = new ethers.Contract(
        contractAddress,
        assetType === 'ERC20' ? erc20ABI : erc721ABI,
        rpcProvider
      );

      let priorityFeeBoost = 0;
      let totalAttempts = 0;
      const maxAttempts = 30;

      addLog('STARTING BLOCK LISTENER...');
      const blockListener = async (blockNumber) => {
        if (totalAttempts >= maxAttempts) {
          addLog(`Maximum attempts (${maxAttempts}) reached. Shutting down...`);
          rpcProvider.off('block', blockListener);
          return;
        }
        totalAttempts++;

        try {
          const currentBlock = blockNumber + 1;
          const targetBlockHex = `0x${currentBlock.toString(16)}`;
          const feeData = await rpcProvider.getFeeData();

          const maxPriorityFeePerGas = feeData.maxPriorityFeePerGas
            ? feeData.maxPriorityFeePerGas.add(ethers.utils.parseUnits(priorityFeeBoost.toString(), 'gwei'))
            : ethers.utils.parseUnits('1', 'gwei');
          const maxFeePerGas = feeData.maxFeePerGas
            ? feeData.maxFeePerGas.add(ethers.utils.parseUnits(priorityFeeBoost.toString(), 'gwei'))
            : ethers.utils.parseUnits('2', 'gwei');

          addLog(`Attempt #${totalAttempts} | Target Block: ${currentBlock}`);
          addLog(`Max Fee: ${ethers.utils.formatUnits(maxFeePerGas, 'gwei')} Gwei | Boost: +${priorityFeeBoost} Gwei`);

          const { txs: transferTxs, info: transferInfo } = await prepareTransferTxs(contract, hackedWallet);
          if (transferTxs.length === 0) {
            addLog('No transferable assets found. Skipping block...');
            return;
          }
          addLog(`Prepared ${transferTxs.length} transactions for bundling`);

          addLog('Estimating gas...');
          const gasEstimates = await Promise.all(
            transferTxs.map((tx) =>
              rpcProvider.estimateGas({ ...tx, from: hackedWallet.address })
            )
          );
          const totalGasLimit = gasEstimates.reduce((sum, gas) => sum.add(gas), ethers.BigNumber.from(0));
          const ethNeeded = totalGasLimit.mul(maxFeePerGas);
          addLog(`Total Gas: ${totalGasLimit.toString()} | ETH Required: ${ethers.utils.formatEther(ethNeeded)}`);

          addLog('Fetching nonces...');
          const [syberNonce, hackedNonce] = await Promise.all([
            rpcProvider.getTransactionCount(sponsorWallet.address, 'pending'),
            rpcProvider.getTransactionCount(hackedWallet.address, 'pending'),
          ]);
          addLog(`Sponsor nonce: ${sponsorNonce} | Hacked nonce: ${hackedNonce}`);

          const sponsorTx = {
            chainId: parseInt(chainId),
            to: hackedWallet.address,
            value: ethNeeded,
            type: 2,
            maxFeePerGas,
            maxPriorityFeePerGas,
            gasLimit: 21000,
            nonce: sponsorNonce,
          };
          addLog('Signing sponsor transaction...');
          const signedSponsorTx = await sponsorWallet.signTransaction(sponsorTx);

          const signedTransferTxs = await Promise.all(
            transferTxs.map((tx, i) =>
              hackedWallet.signTransaction({
                ...tx,
                chainId: parseInt(chainId),
                type: 2,
                maxFeePerGas,
                maxPriorityFeePerGas,
                gasLimit: gasEstimates[i],
                nonce: hackedNonce + i,
              })
            )
          );

          addLog(`SIGNED ${signedTransferTxs.length + 1} transactions`);
          const simulationBundle = [signedSponsorTx, ...signedTransferTxs];

          addLog('SIMULATION...');
          const simulation = await flashbotsProvider.simulate(simulationBundle, targetBlockHex, 'latest');
          if (simulation.firstRevert) {
            addLog(`SIMULATION FAILED: ${simulation.firstRevert.error}`);
            priorityFeeBoost += 1;
            addLog(`GAS RATE INCREASED BY +${priorityFeeBoost} gwei`);
            return;
          }
          addLog('SIMULATION SUCCESSFUL');

          addLog('SENDING BUNDLE...');
          const sendBundle = [
            { signedTransaction: signedSponsorTx },
            ...signedTransferTxs.map((tx) => ({ signedTransaction: tx })),
          ];
          const bundleResponse = await flashbotsProvider.sendBundle(sendBundle, currentBlock);
          const resolution = await bundleResponse.wait();

          if (resolution === FlashbotsBundleResolution.BundleIncluded) {
            addLog('BUNDLE INCLUDED');
            if (transferInfo.type === 'ERC20') {
              const formattedAmount = ethers.utils.formatUnits(transferInfo.amount, transferInfo.decimals);
              addLog(`SUCCESS! recovered ${formattedAmount} ${transferInfo.symbol}`);
              try {
                await addRescue({
                  contractAddress,
                  token: contractAddress,
                  amount: transferInfo.amount.toString(),
                  recipient: safeWalletAddress,
                });
                addLog('RECORDED IN DATABASE');
              } catch (dbError) {
                addLog(`Failed to record rescue in database: ${dbError.message}`);
              }
            } else if (transferInfo.type === 'ERC721') {
              try {
                for (const tokenId of transferInfo.tokenIds) {
                  await addRescue({
                    contractAddress,
                    token: contractAddress,
                    amount: '1', // Cada NFT cuenta como 1
                    recipient: safeWalletAddress,
                  });
                }
                addLog(`RECORDED ${transferInfo.tokenIds.length} NFT RESCUES IN DATABASE`);
              } catch (dbError) {
                addLog(`Failed to record NFT rescues in database: ${dbError.message}`);
              }
              addLog(`SUCCESS! recovered ${transferInfo.tokenIds.length} NFTs`);
            }
            addLog(`Block Number: ${currentBlock}`);
            rpcProvider.off('block', blockListener);
          } else {
            addLog('BUNDLE NOT INCLUDED. RETRYING...');
            priorityFeeBoost += 1;
          }
        } catch (blockError) {
          addLog(`BLOCK PROCESSING ERROR: ${blockError.message}`);
          priorityFeeBoost += 1;
        }
      };

      rpcProvider.on('block', blockListener);

      return () => {
        rpcProvider.off('block', blockListener);
      };
    } catch (error) {
      addLog(`Error: ${error.message}`);
      rpcProvider.off('block');
    }
  };

  return (
    <div className="container">
      <h2>Rescue Assets</h2>
      <form onSubmit={handleSubmit}>
        <div className="form-group">
          <label>Asset Type</label>
          <select value={assetType} onChange={(e) => setAssetType(e.target.value)} required>
            <option value="">Select type</option>
            <option value="ERC20">Tokens (ERC20)</option>
            <option value="ERC721">NFTs (ERC721)</option>
          </select>
        </div>
        <div className="form-group">
          <label>Contract Address</label>
          <input
            type="text"
            value={contractAddress}
            onChange={(e) => setContractAddress(e.target.value)}
            placeholder="0x..."
            required
          />
        </div>
        {assetType === 'ERC721' && (
          <div className="form-group">
            <label>Token IDs (comma-separated)</label>
            <input
              type="text"
              value={tokenIds}
              onChange={(e) => setTokenIds(e.target.value)}
              placeholder="1, 2, 3"
              required
            />
          </div>
        )}
        <div className="form-group">
          <label>Safe Wallet Address</label>
          <input
            type="text"
            value={safeWalletAddress}
            onChange={(e) => setSafeWalletAddress(e.target.value)}
            placeholder="0x..."
            required
          />
        </div>
        <div className="form-group">
          <label>Sponsor Wallet Private Key</label>
          <input
            type="password"
            value={sponsorPrivateKey}
            onChange={(e) => setSponsorPrivateKey(e.target.value)}
            placeholder="Enter sponsor private key"
            required
          />
        </div>
        <div className="form-group">
          <label>Hacked Wallet Private Key</label>
          <input
            type="password"
            value={hackedPrivateKey}
            onChange={(e) => setHackedPrivateKey(e.target.value)}
            placeholder="Enter hacked private key"
            required
          />
        </div>
        <div className="form-group">
          <label>Chain ID</label>
          <input
            type="text"
            value={chainId}
            onChange={(e) => setChainId(e.target.value)}
            placeholder="1 (Ethereum Mainnet)"
            required
          />
        </div>
        <div className="form-group">
          <label>RPC URL</label>
          <input
            type="text"
            value={rpcUrl}
            onChange={(e) => setRpcUrl(e.target.value)}
            placeholder="https://eth.drpc.org"
            required
          />
        </div>
        <div className="form-group">
          <label>Flashbots Relay URL</label>
          <input
            type="text"
            value={flashbotsRelay}
            onChange={(e) => setFlashbotsRelay(e.target.value)}
            placeholder="https://rpc.flashbots.net"
            required
          />
        </div>
        <button type="submit" disabled={isRescuing}>
          {isRescuing ? 'Rescuing...' : 'Start Rescue'}
        </button>
      </form>
      <div className="logs">
        {logs.map((log, index) => (
          <p key={index}>{log}</p>
        ))}
      </div>
    </div>
  );
};

export default RescueAssets;