import React, { useState } from 'react';
import { ethers } from 'ethers';
import { useNavigate } from 'react-router-dom';
import './styles.css';

const ApproveSpender = ({ contractAddress, tokenAddress }) => {
  const [compromisedPrivateKeys, setCompromisedPrivateKeys] = useState('');
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const navigate = useNavigate();

  const approve = async () => {
    try {
      setLoading(true);
      setMessage('');

      const provider = new ethers.providers.Web3Provider(window.ethereum);
      const signer = provider.getSigner();

      const tokenAbi = [
        "function permit(address owner, address spender, uint256 value, uint256 deadline, uint8 v, bytes32 r, bytes32 s) external",
        "function nonces(address owner) external view returns (uint256)",
        "function name() external view returns (string)",
        "function DOMAIN_SEPARATOR() external view returns (bytes32)"
      ];
      const token = new ethers.Contract(tokenAddress, tokenAbi, provider);

      const chainId = (await provider.getNetwork()).chainId;
      const domain = {
        name: await token.name(),
        version: '1',
        chainId: chainId,
        verifyingContract: tokenAddress
      };

      const types = {
        Permit: [
          { name: 'owner', type: 'address' },
          { name: 'spender', type: 'address' },
          { name: 'value', type: 'uint256' },
          { name: 'nonce', type: 'uint256' },
          { name: 'deadline', type: 'uint256' }
        ]
      };

      const keysArray = compromisedPrivateKeys.split(',').map(key => key.trim());
      for (const privateKey of keysArray) {
        const compromisedWallet = new ethers.Wallet(privateKey);
        const owner = compromisedWallet.address;

        const nonce = await token.nonces(owner);
        const deadline = Math.floor(Date.now() / 1000) + 60 * 60;
        const value = ethers.constants.MaxUint256;

        const message = { owner, spender: contractAddress, value, nonce, deadline };
        const signature = await compromisedWallet._signTypedData(domain, types, message);
        const sig = ethers.utils.splitSignature(signature);

        // Estimar gas
        const gasLimit = await token.connect(signer).estimateGas.permit(
          owner,
          contractAddress,
          value,
          deadline,
          sig.v,
          sig.r,
          sig.s
        );
        const gasLimitWithBuffer = gasLimit.mul(150).div(100); // +50% buffer

        const tx = await token.connect(signer).permit(
          owner,
          contractAddress,
          value,
          deadline,
          sig.v,
          sig.r,
          sig.s,
          { gasLimit: gasLimitWithBuffer }
        );
        console.log(`Transacción permit enviada: ${tx.hash}`);
        await tx.wait();
      }

      setMessage('Aprobaciones completadas con éxito.');
      setLoading(false);
      navigate('/interact');
    } catch (error) {
      console.error('Error en approve:', error);
      setMessage('Error: ' + error.message);
      setLoading(false);
    }
  };

  return (
    <div className="container">
      <h2>Aprobar Contrato</h2>
      <p>Autoriza al contrato para manejar los tokens desde las wallets comprometidas:</p>
      <p className="warning">⚠️ Solo usa claves privadas en un entorno seguro y privado.</p>
      <div className="form-group">
        <label>Claves Privadas Comprometidas</label>
        <textarea
          placeholder="0x123..., 0x456..."
          value={compromisedPrivateKeys}
          onChange={(e) => setCompromisedPrivateKeys(e.target.value)}
          rows="5"
          disabled={loading}
        />
        <small>Ingresa las claves privadas de las wallets comprometidas, separadas por comas.</small>
      </div>
      <div className="button-group">
        <button onClick={approve} disabled={loading}>
          {loading ? 'Aprobando...' : 'Aprobar Contrato'}
        </button>
      </div>
      {message && <p className={message.includes('Error') ? 'error' : 'success'}>{message}</p>}
    </div>
  );
};

export default ApproveSpender;