import React, { useState, useEffect } from 'react';
import { ethers } from 'ethers';
import ApproveSpender from './ApproveSpender';
import ApproveSpenderBSC from './ApproveSpenderBSC';

const ApproveSpenderLoader = (props) => {
  const [chainId, setChainId] = useState(null);

  useEffect(() => {
    const getChainId = async () => {
      const provider = new ethers.providers.Web3Provider(window.ethereum);
      const network = await provider.getNetwork();
      setChainId(network.chainId);
    };
    getChainId();
  }, []);

  if (chainId === null) return <div className="container">Cargando red...</div>;

  // Cargar ApproveSpenderBSC para BSC (chainId 56), ApproveSpender para el resto
  // Si también falla en Polygon, puedes añadir chainId === 137 aquí
  return chainId === 56 ? <ApproveSpenderBSC {...props} /> : <ApproveSpender {...props} />;
};

export default ApproveSpenderLoader;