const parseClaimInput = (input: string, abi: any[], argsInput: string, compromisedAddress: string): `0x${string}` => {
  // Normalize input by removing parentheses and trimming
  const cleanedInput = input.replace(/\(\)/g, '').trim();

  // Check if input is valid hex data
  if (isHex(input) && input.length >= 10) {
    return input as `0x${string}`;
  }

  // Parse arguments from argsInput (e.g., "0x123,1000" or "{\"recipient\": \"0x123\", \"amount\": 1000}")
  let args: any[] = [];
  if (argsInput) {
    try {
      // Try parsing as JSON
      const parsed = JSON.parse(argsInput);
      args = Array.isArray(parsed) ? parsed : [parsed.recipient || parsed.amount || parsed];
    } catch {
      // Fallback to comma-separated values
      args = argsInput.split(',').map((arg) => {
        arg = arg.trim();
        if (isAddress(arg)) return getAddress(arg);
        if (/^\d+$/.test(arg)) return BigInt(arg);
        return arg;
      });
    }
  }

  // Try to encode with provided function name
  try {
    // Generate dynamic ABI for the function name if not in airdropAbi
    const dynamicAbi = [
      ...abi,
      {
        name: cleanedInput,
        type: 'function',
        inputs: args.map((arg, i) => ({
          name: `_arg${i}`,
          type: isAddress(arg) ? 'address' : typeof arg === 'bigint' ? 'uint256' : 'string',
        })),
        outputs: [],
        stateMutability: 'nonpayable',
      },
    ];

    // Try encoding with existing and dynamic ABI
    const functionNames = [cleanedInput, 'claimTokens', 'claim', 'withdraw', 'unstake'];
    for (const fnName of functionNames) {
      try {
        // Adjust arguments based on function signature
        let finalArgs = args;
        const abiEntry = dynamicAbi.find((entry) => entry.name === fnName);
        if (abiEntry && abiEntry.inputs.length > 0) {
          // If function expects an address as first arg, use compromisedAddress if not provided
          if (abiEntry.inputs[0].type === 'address' && !isAddress(finalArgs[0])) {
            finalArgs = [getAddress(compromisedAddress), ...finalArgs];
          }
        }

        return encodeFunctionData({
          abi: dynamicAbi,
          functionName: fnName,
          args: finalArgs,
        }) as `0x${string}`;
      } catch {
        continue;
      }
    }

    // Fallback to claimTokens
    return encodeFunctionData({
      abi,
      functionName: 'claimTokens',
      args: [],
    }) as `0x${string}`;
  } catch (error) {
    console.warn(`Invalid claim input: ${input}. Args: ${argsInput}. Using default claimTokens.`);
    return encodeFunctionData({
      abi,
      functionName: 'claimTokens',
      args: [],
    }) as `0x${string}`;
  }
};

