// InteractContract.js
import React, { useState, useEffect } from 'react';
import { ethers } from 'ethers';
import RescueTokensV3 from './contracts/RescueTokensV3.json';
import { addTransaction } from './db'; // Importar addTransaction
import './styles.css';

const InteractContract = ({ contractAddress, compromisedWallets }) => {
  const [amount, setAmount] = useState('');
  const [selectedWallet, setSelectedWallet] = useState('');
  const [message, setMessage] = useState('');
  const [tokenDecimals] = useState(18);
  const [loading, setLoading] = useState(false);

  const contract = new ethers.Contract(
    contractAddress,
    RescueTokensV3.abi,
    new ethers.providers.Web3Provider(window.ethereum).getSigner()
  );

  const fund = async () => {
    try {
      setLoading(true);
      const tx = await contract.fundContract({ value: ethers.utils.parseEther(amount) });
      setMessage(`Transacción enviada: ${tx.hash}`);
      await tx.wait();
      setMessage('Fondos enviados con éxito');
      addToHistory('Fund Contract', amount);
    } catch (error) {
      setMessage('Error: ' + error.message);
    } finally {
      setLoading(false);
    }
  };

  const rescue = async (amountToRescue) => {
    try {
      if (!selectedWallet) throw new Error('Selecciona una wallet comprometida');
      setLoading(true);
      const amountInUnits = ethers.utils.parseUnits(amountToRescue, tokenDecimals);
      const tx = await contract.rescue(selectedWallet, amountInUnits);
      setMessage(`Transacción enviada: ${tx.hash}`);
      await tx.wait();
      setMessage('Tokens rescatados con éxito');
      // Registrar transacción en la base de datos
      await addTransaction({
        contractAddress,
        type: 'Rescue',
        details: `Rescatado ${amountToRescue} tokens desde ${selectedWallet} (tx: ${tx.hash})`,
      });
      addToHistory('Rescue Tokens', `${amountToRescue} tokens from ${selectedWallet}`);
    } catch (error) {
      if (error.reason === 'execution reverted: Insufficient token balance') {
        const balance = await contract.checkTokenBalance(selectedWallet);
        setMessage(
          `La wallet tiene solo ${ethers.utils.formatUnits(balance, tokenDecimals)} tokens, pero intentaste rescatar ${amount} tokens.`
        );
      } else {
        setMessage('Error: ' + error.message);
      }
    } finally {
      setLoading(false);
    }
  };

  const rescueAll = async () => {
    try {
      if (!selectedWallet) throw new Error('Selecciona una wallet comprometida');
      setLoading(true);
      const balance = await contract.checkTokenBalance(selectedWallet);
      const balanceFormatted = ethers.utils.formatUnits(balance, tokenDecimals);
      const tx = await contract.rescue(selectedWallet, balance);
      setMessage(`Transacción enviada: ${tx.hash}`);
      await tx.wait();
      setMessage('Todos los tokens han sido rescatados');
      // Registrar transacción en la base de datos
      await addTransaction({
        contractAddress,
        type: 'RescueAll',
        details: `Rescatado ${balanceFormatted} tokens desde ${selectedWallet} (tx: ${tx.hash})`,
      });
      addToHistory('Rescue All', `${balanceFormatted} tokens from ${selectedWallet}`);
    } catch (error) {
      setMessage('Error: ' + error.message);
    } finally {
      setLoading(false);
    }
  };

  const checkTokenBalance = async () => {
    try {
      if (!selectedWallet) throw new Error('Debes especificar la wallet comprometida para consultar su balance');
      const balance = await contract.checkTokenBalance(selectedWallet);
      setMessage(`Balance: ${ethers.utils.formatUnits(balance, tokenDecimals)} tokens`);
    } catch (error) {
      setMessage(error.message || 'Error: ' + error);
    }
  };

  const checkAllowance = async () => {
    try {
      if (!selectedWallet) throw new Error('Debes especificar la wallet comprometida para consultar su aprobación');
      const allowance = await contract.checkAllowance(selectedWallet);
      setMessage(`Allowance: ${ethers.utils.formatUnits(allowance, tokenDecimals)} tokens`);
    } catch (error) {
      setMessage(error.message || 'Error: ' + error);
    }
  };

  const checkETHBalance = async () => {
    try {
      const balance = await contract.checkETHBalance();
      setMessage(`ETH en el contrato: ${ethers.utils.formatEther(balance)} ETH`);
    } catch (error) {
      setMessage('Error: ' + error.message);
    }
  };

  const withdrawETH = async () => {
    try {
      setLoading(true);
      const tx = await contract.withdrawETH();
      setMessage(`Transacción enviada: ${tx.hash}`);
      await tx.wait();
      setMessage('ETH retirado con éxito');
      addToHistory('Withdraw ETH', 'All ETH');
    } catch (error) {
      setMessage('Error: ' + error.message);
    } finally {
      setLoading(false);
    }
  };

  const addToHistory = (action, details) => {
    const history = JSON.parse(localStorage.getItem('drainerlessHistory') || '[]');
    history.push({ action, details, timestamp: new Date().toISOString() });
    localStorage.setItem('drainerlessHistory', JSON.stringify(history));
  };

  return (
    <div className="container">
      <h2>Interactuar con el Contrato</h2>
      <p>Dirección del contrato: {contractAddress}</p>
      <div className="form-group">
        <label>Cantidad</label>
        <input
          type="text"
          placeholder="ETH o Tokens"
          value={amount}
          onChange={(e) => setAmount(e.target.value)}
          disabled={loading}
        />
        <small>Ingresa la cantidad en ETH (para fondos) o tokens (para rescatar).</small>
      </div>
      <div className="form-group">
        <label>Wallet Comprometida</label>
        <select
          value={selectedWallet}
          onChange={(e) => setSelectedWallet(e.target.value)}
          disabled={loading}
        >
          <option value="">Selecciona una wallet</option>
          {compromisedWallets.map((wallet, index) => (
            <option key={index} value={wallet}>{wallet}</option>
          ))}
        </select>
        <small>Elige una wallet comprometida configurada al crear el contrato.</small>
      </div>
      <div className="button-group">
        <button onClick={fund} disabled={loading}>Enviar Fondos</button>
        <button onClick={() => rescue(amount)} disabled={loading || !selectedWallet}>Rescatar Tokens</button>
        <button onClick={rescueAll} disabled={loading || !selectedWallet}>Rescatar Todo</button>
        <button onClick={checkTokenBalance} disabled={loading}>Ver Balance</button>
        <button onClick={checkAllowance} disabled={loading}>Ver Allowance</button>
        <button onClick={checkETHBalance} disabled={loading}>Ver ETH</button>
        <button onClick={withdrawETH} disabled={loading}>Retirar ETH</button>
      </div>
      {message && <p className={message.includes('Error') ? 'error' : 'success'}>{message}</p>}
    </div>
  );
};

export default InteractContract;