import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';

const ChainSearch = ({ onClose }) => {
  const { t } = useTranslation();
  const [query, setQuery] = useState('');
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [copiedIndex, setCopiedIndex] = useState(null);

  const handleSearch = async (e) => {
    e.preventDefault();
    if (!query.trim()) return;

    setLoading(true);
    setError(null);
    setResults([]);

    try {
      const response = await fetch('https://chainlist.org/rpcs.json');
      if (!response.ok) throw new Error('Failed to fetch RPCs');
      const data = await response.json();

      // Filter networks by query (case-insensitive)
      const filtered = data.filter((chain) =>
        chain.name.toLowerCase().includes(query.toLowerCase())
      );

      // Get top 5 RPC URLs for the first matching network
      const topRpcs = filtered.length > 0 ? filtered[0].rpc.slice(0, 10).map(rpc => rpc.url) : [];
      setResults(topRpcs);
    } catch (err) {
      setError(t('search_error'));
    } finally {
      setLoading(false);
    }
  };

  const handleCopy = (url, index) => {
    navigator.clipboard.writeText(url).then(() => {
      setCopiedIndex(index);
      setTimeout(() => setCopiedIndex(null), 2000); // Reset after 2 seconds
    });
  };

  return (
    <div className="chain-search">
      <button className="close-search" onClick={onClose}>
        ✕
      </button>
      <h3>{t('search_network')}</h3>
      <form onSubmit={handleSearch}>
        <input
          type="text"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder={t('search_placeholder')}
          aria-label={t('search_network')}
        />
        <button type="submit" disabled={loading}>
          {loading ? t('searching') : t('search')}
        </button>
      </form>
      {error && <p className="error">{error}</p>}
      {results.length > 0 && (
        <ul className="rpc-results">
          {results.map((url, index) => (
            <li key={index} onClick={() => handleCopy(url, index)} className="rpc-item">
              <span className="rpc-url">{url}</span>
              <span className="copy-status">{copiedIndex === index ? t('copied') : t('click_to_copy')}</span>
            </li>
          ))}
        </ul>
      )}
      {results.length === 0 && !loading && !error && query && (
        <p>{t('no_results')}</p>
      )}
    </div>
  );
};

export default ChainSearch;